    {
      "path": "packages/dsh-plugin/cordis.patch.yml",
      "content": "# next-ai-drawio for DeepSeek Harness\n#\n# Mounts the @next-ai-drawio/mcp-server MCP server over stdio. Its tools show\n# up as mcp__drawio__start_session, mcp__drawio__create_new_diagram and so on.\n# start_session returns the preview link; clicking it in the chat opens the\n# live preview in DSH's right sidebar.\n#\n# Install through DSH's plugin manager: dsh plugin --profile web add @next-ai-drawio/dsh\n\n- insert:\n    - id: mcp-drawio\n      name: '@deepseek-ai/dsh-mcp-client'\n      config:\n        serverName: drawio\n        transport: stdio\n        command: npx\n        args: ['-y', '@next-ai-drawio/mcp-server@latest']\n        # Screenshots and exports can take longer than the 60 s default.\n        toolCallTimeoutMs: 120000\n        env:\n          # Let DSH's sidebar browser frame the preview page\n          DRAWIO_ALLOW_EMBED: 'true'\n          # Give the link in the chat instead of opening a browser tab\n          BROWSER: none\n\n# The sidebar browser is off by default in the web profile\n- id: ui-sidebar-browser\n  disabled: false\n"
    },
    {
      "path": "packages/mcp-server/package.json",
      "content": "{\n    \"name\": \"@next-ai-drawio/mcp-server\",\n    \"version\": \"0.4.13\",\n    \"description\": \"draw.io MCP server for Claude Code, Cursor, Codex and VS Code: the AI draws on a live browser canvas you can also edit by hand, with versions and undo\",\n    \"mcpName\": \"io.github.DayuanJiang/next-ai-drawio\",\n    \"type\": \"module\",\n    \"main\": \"dist/index.js\",\n    \"bin\": {\n        \"next-ai-drawio-mcp\": \"./dist/index.js\"\n    },\n    \"scripts\": {\n        \"build\": \"tsc && tsc -p shell && node scripts/copy-assets.mjs && node scripts/fetch-drawio.mjs && node scripts/build-shell.mjs\",\n        \"check-drawio\": \"node scripts/check-drawio-files.mjs\",\n        \"check-package\": \"node scripts/check-package.mjs\",\n        \"dev\": \"tsx watch src/index.ts\",\n        \"start\": \"node dist/index.js\",\n        \"test\": \"vitest run\",\n        \"test:watch\": \"vitest\",\n        \"test:e2e\": \"playwright test\",\n        \"prepublishOnly\": \"npm run build\"\n    },\n    \"keywords\": [\n        \"mcp\",\n        \"mcp-server\",\n        \"drawio\",\n        \"draw.io\",\n        \"diagrams.net\",\n        \"diagram\",\n        \"architecture-diagram\",\n        \"flowchart\",\n        \"ai\",\n        \"claude\",\n        \"claude-code\",\n        \"cursor\",\n        \"codex\",\n        \"model-context-protocol\"\n    ],\n    \"author\": \"DayuanJiang\",\n    \"license\": \"Apache-2.0\",\n    \"repository\": {\n        \"type\": \"git\",\n        \"url\": \"https://github.com/DayuanJiang/next-ai-draw-io\",\n        \"directory\": \"packages/mcp-server\"\n    },\n    \"homepage\": \"https://github.com/DayuanJiang/next-ai-draw-io/tree/main/packages/mcp-server#readme\",\n    \"bugs\": {\n        \"url\": \"https://github.com/DayuanJiang/next-ai-draw-io/issues\"\n    },\n    \"publishConfig\": {\n        \"access\": \"public\"\n    },\n    \"dependencies\": {\n        \"@modelcontextprotocol/sdk\": \"^1.31.0\",\n        \"linkedom\": \"^0.18.0\",\n        \"open\": \"^11.0.0\",\n        \"pako\": \"^2.2.0\",\n        \"saxes\": \"^6.0.0\",\n        \"zod\": \"^4.0.0\"\n    },\n    \"devDependencies\": {\n        \"@types/node\": \"^24.0.0\",\n        \"@types/pako\": \"^2.0.4\",\n        \"tsx\": \"^4.19.0\",\n        \"typescript\": \"^5\",\n        \"vitest\": \"^4.1.8\"\n    },\n    \"engines\": {\n        \"node\": \">=18\"\n    },\n    \"files\": [\n        \"dist\"\n    ]\n}\n"
    },
    {
      "path": "packages/mcp-server/shell/canvas-shell.tsx",
      "content": "import {\n    Download,\n    History,\n    MessageSquareWarning,\n    Moon,\n    Sun,\n} from \"lucide-react\"\nimport { useEffect, useMemo, useState } from \"react\"\nimport { CanvasStage } from \"@/components/canvas/canvas-stage\"\nimport { CompareDialog } from \"@/components/canvas/compare-dialog\"\nimport { VersionsProvider } from \"@/components/canvas/versions-context\"\nimport { type ExportFormat, SaveDialog } from \"@/components/save-dialog\"\nimport { AppToaster } from \"@/components/workspace/app-toaster\"\nimport { useDiagram } from \"@/contexts/diagram-context\"\nimport { useDictionary } from \"@/hooks/use-dictionary\"\nimport type { DrawioSource } from \"@/lib/drawio/drawio-config\"\nimport { cn } from \"@/lib/utils\"\nimport { useSettingsStore } from \"@/stores/settings-store\"\nimport { feedbackIssueUrl } from \"./feedback\"\nimport { useNodeVersions } from \"./node-versions-source\"\nimport type { ShellConfig } from \"./runtime-config\"\nimport { setDark } from \"./theme\"\nimport { useMcpSync } from \"./use-mcp-sync\"\nimport { VersionsPanel } from \"./versions-panel\"\n\nconst iconButton =\n    \"inline-flex size-8 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-accent hover:text-foreground [&_svg]:size-4\"\n\n/**\n * The MCP preview: the web app's canvas without the chat. A slim bar names\n * the session and the sync state; the version cards (from the server's\n * History), Compare and the export dialog come from the shared canvas\n * components. The cards sit in a side panel, so the web app's versions strip\n * above the canvas is left out: it would show the same list twice.\n */\nexport function CanvasShell({ config }: { config: ShellConfig }) {\n    const dict = useDictionary()\n    const isDark = useSettingsStore((s) => s.isDark)\n    const { saveDiagramToFile, hasPendingLoad } = useDiagram()\n    const { status, sync } = useMcpSync(config)\n    const versions = useNodeVersions(sync)\n    const [panelOpen, setPanelOpen] = useState(true)\n    const [saveOpen, setSaveOpen] = useState(false)\n    // The file the diagram was opened from or saved to (load_diagram,\n    // export_diagram), named instead of the session id, and whether the\n    // diagram changed since: the file changes only on export_diagram\n    const [file, setFile] = useState<string | null>(null)\n    const [fileChanged, setFileChanged] = useState(false)\n    useEffect(() => {\n        if (!sync) return\n        const readFile = () => {\n            setFile(sync.read().file)\n            setFileChanged(sync.read().fileChanged)\n        }\n        readFile()\n        return sync.onServerChange(readFile)\n    }, [sync])\n    const unsaved = !!file && fileChanged\n    const drawioSource = useMemo<DrawioSource>(\n        () => ({\n            editorUrl: config.drawioBaseUrl,\n            ui: config.drawioUi || undefined,\n            lang: config.drawioLang || undefined,\n            // As the classic preview page: the user's own shape libraries\n            libraries: true,\n        }),\n        [config],\n    )\n    const hasVersions = versions.versions.length > 0\n    const showPanel = panelOpen && hasVersions\n\n    // draw.io exports what it shows: while a page export's one-page\n    // projection is on the canvas, or a full load has yet to reach the\n    // editor, that is not the document. Both end within seconds (the\n    // export's deadline is 15 s); the save waits for them, up to 20 s\n    const save = (filename: string, format: ExportFormat, tries = 0) => {\n        const canvasBusy = sync?.read().projectionActive || hasPendingLoad()\n        if (canvasBusy && tries < 66) {\n            setTimeout(() => save(filename, format, tries + 1), 300)\n            return\n        }\n        saveDiagramToFile(\n            filename,\n            format,\n            undefined,\n            dict.save.savedSuccessfully,\n        )\n    }\n\n    return (\n        <VersionsProvider value={versions}>\n            <div className=\"flex h-dvh flex-col bg-background text-foreground\">\n                <header className=\"flex h-11 shrink-0 items-center gap-3 border-b border-border bg-surface-0 px-3.5\">\n                    <span className=\"text-[13px] font-semibold tracking-[-0.01em]\">\n                        Next AI Draw.io\n                    </span>\n                    {config.sessionId && (\n                        <span\n                            className={cn(\n                                \"flex min-w-0 max-w-[40%] gap-1 rounded-md bg-muted px-1.5 py-0.5 text-[11px] text-muted-foreground\",\n                                !file && \"font-mono tabular-nums\",\n                            )}\n                            title={\n                                file\n                                    ? `${file}\\n${unsaved ? `${dict.shell.fileChangedHint}\\n` : \"\"}${config.sessionId}`\n                                    : config.sessionId\n                            }\n                            data-testid=\"shell-session\"\n                        >\n                            <span className=\"truncate\">\n                                {file\n                                    ? file.split(/[\\\\/]/).pop()\n                                    : config.sessionId.split(\"-\").pop() ||\n                                      config.sessionId}\n                            </span>\n                            {unsaved && (\n                                <span\n                                    className=\"shrink-0\"\n                                    data-testid=\"shell-file-changed\"\n                                >\n                                    · {dict.shell.fileChanged}\n                                </span>\n                            )}\n                        </span>\n                    )}\n                    <span\n                        className=\"truncate text-xs text-muted-foreground\"\n                        data-testid=\"shell-status\"\n                        data-status={status}\n                    >\n                        {dict.shell[status]}\n                    </span>\n                    {hasVersions && (\n                        <button\n                            type=\"button\"\n                            onClick={() => setPanelOpen((open) => !open)}\n                            aria-label={\n                                panelOpen\n                                    ? dict.shell.hideVersions\n                                    : dict.shell.showVersions\n                            }\n                            title={\n                                panelOpen\n                                    ? dict.shell.hideVersions\n                                    : dict.shell.showVersions\n                            }\n                            aria-pressed={panelOpen}\n                            className={cn(\n                                iconButton,\n                                \"ml-auto\",\n                                panelOpen && \"bg-accent text-foreground\",\n                            )}\n                            data-testid=\"versions-toggle\"\n                        >\n                            <History />\n                        </button>\n                    )}\n                    <button\n                        type=\"button\"\n                        onClick={() => setSaveOpen(true)}\n                        aria-label={dict.workspace.export}\n                        title={dict.workspace.export}\n                        className={cn(iconButton, !hasVersions && \"ml-auto\")}\n                        data-testid=\"download\"\n                    >\n                        <Download />\n                    </button>\n                    <a\n                        href={feedbackIssueUrl(config, navigator.userAgent)}\n                        target=\"_blank\"\n                        rel=\"noopener noreferrer\"\n                        aria-label={dict.shell.feedback}\n                        title={dict.shell.feedback}\n                        className={iconButton}\n                        data-testid=\"feedback\"\n                    >\n                        <MessageSquareWarning />\n                    </a>\n                    <button\n                        type=\"button\"\n                        onClick={() => setDark(!isDark)}\n                        aria-label={dict.shell.toggleTheme}\n                        title={dict.shell.toggleTheme}\n                        className={iconButton}\n                        data-testid=\"theme-toggle\"\n                    >\n                        {isDark ? <Sun /> : <Moon />}\n                    </button>\n                </header>\n                <div className=\"flex min-h-0 flex-1\">\n                    <div className=\"relative min-w-0 flex-1\">\n                        <CanvasStage\n                            className=\"inset-0\"\n                            drawioSource={drawioSource}\n                        />\n                    </div>\n                    {showPanel && (\n                        <VersionsPanel versions={versions.versions} />\n                    )}\n                </div>\n                <CompareDialog />\n                <SaveDialog\n                    open={saveOpen}\n                    onOpenChange={setSaveOpen}\n                    onSave={save}\n                    defaultFilename={`diagram-${new Date().toLocaleDateString(\"sv-SE\")}`}\n                />\n                <AppToaster />\n            </div>\n        </VersionsProvider>\n    )\n}\n"
    },
    {
      "path": "packages/mcp-server/shell/feedback.ts",
      "content": "import type { ShellConfig } from \"./runtime-config\"\n\nconst ISSUES_URL = \"https://github.com/DayuanJiang/next-ai-draw-io/issues/new\"\n\n/**\n * A new GitHub issue about the MCP server with the environment filled in.\n * The server sends nothing anywhere, so this is the way to tell us.\n */\nexport function feedbackIssueUrl(\n    config: ShellConfig,\n    userAgent: string,\n): string {\n    const drawio = config.drawioBaseUrl.startsWith(\"/\")\n        ? \"bundled copy\"\n        : config.drawioBaseUrl\n    const body = [\n        \"## What happened\",\n        \"\",\n        \"\",\n        \"## What you expected\",\n        \"\",\n        \"\",\n        \"## Environment\",\n        `- MCP server: ${config.version || \"unknown\"}`,\n        \"- MCP client (Claude Code, Cursor, Codex, VS Code...): \",\n        `- draw.io: ${drawio}`,\n        `- Browser: ${userAgent}`,\n    ].join(\"\\n\")\n    return `${ISSUES_URL}?${new URLSearchParams({ title: \"[MCP] \", body })}`\n}\n"
    },
    {
      "path": "packages/mcp-server/src/http-server.ts",
      "content": "/**\n * Embedded HTTP Server for MCP\n * Serves draw.io embed with state sync and history UI\n */\n\nimport { randomBytes, randomUUID } from \"node:crypto\"\nimport { createReadStream, existsSync, readFileSync, statSync } from \"node:fs\"\nimport http from \"node:http\"\nimport { dirname, extname, join, posix, resolve, sep } from \"node:path\"\nimport { pipeline } from \"node:stream\"\nimport { fileURLToPath } from \"node:url\"\n\nconst MAX_BODY_BYTES = 10 * 1024 * 1024 // 10 MiB\n\nfunction readBody(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n    cb: (body: string) => void,\n): void {\n    // Decode once at the end: a multi-byte UTF-8 character can be split\n    // across two chunks.\n    const chunks: Buffer[] = []\n    let size = 0\n    let tooLarge = false\n    req.on(\"data\", (chunk: Buffer) => {\n        if (tooLarge) return\n        size += chunk.length\n        if (size > MAX_BODY_BYTES) {\n            // Read the rest without keeping it and answer at the end: a\n            // connection closed mid-upload reaches the browser as a network\n            // error, without this answer\n            tooLarge = true\n            chunks.length = 0\n            return\n        }\n        chunks.push(chunk)\n    })\n    req.on(\"end\", () => {\n        if (tooLarge) {\n            res.writeHead(413, { \"Content-Type\": \"application/json\" })\n            res.end(JSON.stringify({ error: \"Payload too large\" }))\n            return\n        }\n        cb(Buffer.concat(chunks).toString(\"utf8\"))\n    })\n}\n\nimport { isDrawioTheme, toDrawioLang } from \"./drawio-themes.ts\"\nimport { contentFingerprint } from \"./edit-gate.ts\"\nimport {\n    addHistory,\n    clearHistory,\n    currentEntryId,\n    firstCopyIds,\n    getHistory,\n    getHistoryEntry,\n    updateLastHistorySvg,\n} from \"./history.ts\"\nimport { log } from \"./logger.ts\"\nimport { BLANK_MXFILE } from \"./pages.ts\"\nimport { parseSelectionAnswer, type SelectionAnswer } from \"./selection.ts\"\n\n// Configurable draw.io embed URL for private deployments. Set, it replaces\n// the bundled copy (see drawioDir below).\nexport const DRAWIO_BASE_URL =\n    process.env.DRAWIO_BASE_URL || \"https://embed.diagrams.net\"\nconst EXTERNAL_DRAWIO = !!process.env.DRAWIO_BASE_URL\n\n// Every /api request must carry this token in the X-Drawio-Token header.\n// The page reads it from its HTML. Another website cannot add a custom\n// header without a CORS preflight, which this server never grants, so its\n// requests stop here whatever Host and Origin they manage to send.\nconst API_TOKEN = randomBytes(16).toString(\"hex\")\n\nexport function getApiToken(): string {\n    return API_TOKEN\n}\n\n// The trimmed draw.io copy that scripts/fetch-drawio.mjs puts in dist/drawio,\n// next to the compiled server; run from src with tsx, it is one level up\nconst HERE = dirname(fileURLToPath(import.meta.url))\nlet drawioDir: string | null =\n    [join(HERE, \"drawio\"), join(HERE, \"../dist/drawio\")].find((dir) =>\n        existsSync(join(dir, \"index.html\")),\n    ) ?? null\nlet drawioVersion = readDrawioVersion(drawioDir)\n\n/** For tests: serve draw.io from this directory (null: no bundled copy) */\nexport function setDrawioDir(dir: string | null): void {\n    drawioDir = dir\n    drawioVersion = readDrawioVersion(dir)\n}\n\n// The canvas shell (the web app's canvas without the chat), built by\n// scripts/build-shell.mjs into dist/shell\nlet shellDir: string | null =\n    [join(HERE, \"shell\"), join(HERE, \"../dist/shell\")].find((dir) =>\n        existsSync(join(dir, \"index.html\")),\n    ) ?? null\n\n/** For tests: serve the shell from this directory (null: not built) */\nexport function setShellDir(dir: string | null): void {\n    shellDir = dir\n}\n\n// This package's version, stamped into the shell files' ETags (see\n// readDrawioVersion for why)\nconst PACKAGE_VERSION: string = JSON.parse(\n    readFileSync(join(HERE, \"../package.json\"), \"utf8\"),\n).version\n\n/**\n * The preview page start_session opens: the canvas shell (shell/, the web\n * app's canvas), or with DRAWIO_PREVIEW_UI=classic the classic page\n * (src/preview), kept for one more release.\n */\nexport type PreviewUi = \"classic\" | \"shell\"\n\nexport function previewUiFromEnv(\n    env: NodeJS.ProcessEnv = process.env,\n): PreviewUi {\n    return (env.DRAWIO_PREVIEW_UI ?? \"\").toLowerCase() === \"classic\"\n        ? \"classic\"\n        : \"shell\"\n}\n\nexport const PREVIEW_UI: PreviewUi = previewUiFromEnv()\n\n/** One explicitly trusted preview origin, never a path or proxy header. */\nexport function previewOriginFromEnv(\n    env: NodeJS.ProcessEnv = process.env,\n): string | undefined {\n    const value = env.DRAWIO_PREVIEW_URL\n    if (value === undefined) return undefined\n    let url: URL\n    try {\n        url = new URL(value)\n    } catch {\n        throw new Error(\"DRAWIO_PREVIEW_URL must be an absolute origin URL\")\n    }\n    if (\n        value !== value.trim() ||\n        !/^https?:\\/\\//.test(value) ||\n        url.username ||\n        url.password ||\n        url.pathname !== \"/\" ||\n        url.search ||\n        url.hash ||\n        value.includes(\"?\") ||\n        value.includes(\"#\") ||\n        value.includes(\"\\\\\") ||\n        (url.protocol !== \"https:\" &&\n            !(\n                url.protocol === \"http:\" &&\n                [\"localhost\", \"127.0.0.1\"].includes(url.hostname)\n            ))\n    ) {\n        throw new Error(\n            \"DRAWIO_PREVIEW_URL must be an HTTPS origin without credentials, path, query or fragment (HTTP is allowed only for localhost or 127.0.0.1)\",\n        )\n    }\n    // Reject normalized paths (e.g. /a/..) as well as actual subpaths.\n    if (value !== url.origin && value !== `${url.origin}/`) {\n        throw new Error(\n            \"DRAWIO_PREVIEW_URL must use its canonical origin, optionally followed by /\",\n        )\n    }\n    return url.origin\n}\n\nconst PREVIEW_ORIGIN = previewOriginFromEnv()\n\n/**\n * The page start_session actually opens: the classic page stands in while\n * the shell is not built (a run from the sources), as embed.diagrams.net\n * does for a missing dist/drawio\n */\nexport function activePreviewUi(ui: PreviewUi = PREVIEW_UI): PreviewUi {\n    return ui === \"shell\" && shellDir === null ? \"classic\" : ui\n}\n\nexport function previewUrl(\n    port: number,\n    sessionId: string,\n    ui: PreviewUi = PREVIEW_UI,\n): string {\n    const path = activePreviewUi(ui) === \"shell\" ? \"/shell/\" : \"\"\n    return `${PREVIEW_ORIGIN ?? `http://localhost:${port}`}${path}?mcp=${sessionId}`\n}\n\n/**\n * The draw.io version the fetch script stamps into the copy. It is part of\n * every file's ETag: an install that keeps the archive's dates (npm does\n * not) would otherwise hand out the old ETag for a changed file of the\n * same size after an upgrade.\n */\nfunction readDrawioVersion(dir: string | null): string {\n    if (!dir) return \"\"\n    try {\n        return readFileSync(join(dir, \".version\"), \"utf8\").trim()\n    } catch {\n        return \"\"\n    }\n}\n\n/**\n * Whether the preview embeds draw.io from its own origin (the bundled copy),\n * which lets the page call the editor directly. False with DRAWIO_BASE_URL,\n * or when the bundled copy is missing.\n */\nexport function isSameOriginDrawio(): boolean {\n    return !EXTERNAL_DRAWIO && drawioDir !== null\n}\n\n// Extract origin (scheme + host + port) from URL for postMessage security check\nfunction getOrigin(url: string): string {\n    try {\n        const parsed = new URL(url)\n        return `${parsed.protocol}//${parsed.host}`\n    } catch {\n        return url // Fallback if parsing fails\n    }\n}\n\nconst DRAWIO_ORIGIN = getOrigin(DRAWIO_BASE_URL)\n\n// Normalize URL for iframe src - ensure no double slashes\nfunction normalizeUrl(url: string): string {\n    // Remove trailing slash to avoid double slashes\n    return url.replace(/\\/$/, \"\")\n}\n\n// Session ids look like \"mcp-<base36 time>-<base36 random>\" (start_session).\n// Only this charset is accepted, because ids are written into the page's\n// HTML and script and into the redirect Location header.\nfunction isValidSessionId(sessionId: string): boolean {\n    return /^mcp-[a-z0-9-]{1,64}$/.test(sessionId)\n}\n\n// Find the most recent active session (for auto-redirect when no sessionId provided)\nfunction getMostRecentSessionId(): string | null {\n    let mostRecent: { id: string; lastUpdated: Date } | null = null\n    for (const [sessionId, state] of stateStore) {\n        if (!mostRecent || state.lastUpdated > mostRecent.lastUpdated) {\n            mostRecent = { id: sessionId, lastUpdated: state.lastUpdated }\n        }\n    }\n    return mostRecent?.id || null\n}\n\n/**\n * Give a session whose state is gone (it expired, or the MCP process\n * restarted) its auto-saved diagram back. The MCP tools call this before\n * they read the state, so they never build on an older copy and then\n * overwrite the file. Not a change worth saving again.\n */\nexport function restoreSavedSession(sessionId: string): void {\n    if (stateStore.has(sessionId) || !isValidSessionId(sessionId)) return\n    const saved = savedStateLoader?.(sessionId)\n    if (saved) setState(sessionId, saved, undefined, false, false)\n}\n\nfunction ensureSessionStateInitialized(sessionId: string): void {\n    if (!isValidSessionId(sessionId)) return\n    restoreSavedSession(sessionId)\n    if (stateStore.has(sessionId)) return\n\n    // Not a change worth saving: the browser fills it on its next push\n    // A blank diagram keeps the draw.io spinner (spin=1) from waiting\n    // forever when no load(xml) is ever sent\n    setState(sessionId, BLANK_MXFILE, undefined, false, false)\n    // Nothing is known about this session: a tab that still shows it keeps\n    // its diagram\n    const state = stateStore.get(sessionId)\n    if (state) state.blank = true\n}\n\ninterface SessionState {\n    xml: string\n    version: number\n    // Made when the state is created (first use, or again after it expired\n    // or the MCP process restarted) and kept by every write. A tab tells by\n    // it that the server lost what it knew, and every push names the state\n    // it was based on, so one based on a lost state is refused.\n    stateId: string\n    // Created blank because nothing was saved; cleared by the first write\n    blank?: boolean\n    // Version of the last write the browser did not make itself (AI edit,\n    // restore). A browser push based on an older version is rejected.\n    serverVersion?: number\n    // The XML of that write: what a thumbnail taken after loading it shows\n    serverXml?: string\n    // The browser saved a change of the user's since that write (a sync\n    // reply is no change)\n    userEdited?: boolean\n    lastUpdated: Date\n    lastPolled?: number // Last browser poll; an open tab keeps the session alive\n    svg?: string // Cached SVG from last browser save\n    syncRequested?: number // Timestamp when sync requested, cleared when browser responds\n    exportFormat?: ExportFormat // Set by MCP tool to request browser export\n    exportXml?: string // Single-page projection to load before a page-targeted export\n    exportOptions?: ExportOptions // Extra draw.io export parameters\n    exportId?: string // Random id of the pending export, echoed with its result\n    exportData?: string // Base64/SVG data returned by browser after export\n    selectionId?: string // Random id of the pending get_selection request\n    selection?: SelectionAnswer // The page's answer to it\n}\n\n/** draw.io export formats; xmlsvg is an SVG with the diagram embedded */\nexport type ExportFormat = \"png\" | \"svg\" | \"xmlsvg\"\n\n/**\n * draw.io's export takes these directly: width caps the image size (never\n * upscales), pageId renders a page other than the one on screen (both PNG\n * only), border is the margin, background the color behind a page that has\n * none, transparent leaves a PNG without any.\n */\nexport interface ExportOptions {\n    width?: number\n    pageId?: string\n    border?: number\n    background?: string\n    transparent?: boolean\n}\n\nconst stateStore = new Map<string, SessionState>()\n\n// The file each session's diagram was opened from or last saved to\n// (load_diagram, export_diagram), named in the preview's header, and\n// whether the diagram changed since (the file changes only on export);\n// none: a new diagram that is in no file yet\nconst sessionFiles = new Map<string, { path: string; changed: boolean }>()\n\n/** changed: the diagram moved on while the file was written */\nexport function setSessionFile(\n    sessionId: string,\n    path: string | null,\n    changed = false,\n): void {\n    if (path) sessionFiles.set(sessionId, { path, changed })\n    else sessionFiles.delete(sessionId)\n}\n\n// Every change of each session's diagram (AI writes and the user's edits),\n// so an export can tell whether one came in while it ran\nconst changeCounts = new Map<string, number>()\n\nexport function changeCount(sessionId: string): number {\n    return changeCounts.get(sessionId) ?? 0\n}\n\nfunction markFileChanged(sessionId: string): void {\n    changeCounts.set(sessionId, changeCount(sessionId) + 1)\n    const file = sessionFiles.get(sessionId)\n    if (file) file.changed = true\n}\n\nlet server: http.Server | null = null\nlet serverPort = 6002\nconst MAX_PORT = 6020\nconst SESSION_TTL = 60 * 60 * 1000\n\nexport function getState(sessionId: string): SessionState | undefined {\n    return stateStore.get(sessionId)\n}\n\n// Called after every state change (AI write, browser push, restore)\nlet stateListener: ((sessionId: string, xml: string) => void) | null = null\n\nexport function onStateChange(\n    listener: (sessionId: string, xml: string) => void,\n): void {\n    stateListener = listener\n}\n\n// Reads a session's saved diagram when its state is created again (it\n// expired, or the MCP process restarted)\nlet savedStateLoader: ((sessionId: string) => string | null) | null = null\n\nexport function onSessionRecreate(\n    loader: (sessionId: string) => string | null,\n): void {\n    savedStateLoader = loader\n}\n\nexport function setState(\n    sessionId: string,\n    xml: string,\n    svg?: string,\n    fromBrowser = false,\n    notify = true,\n): number {\n    const existing = stateStore.get(sessionId)\n    const newVersion = (existing?.version || 0) + 1\n    stateStore.set(sessionId, {\n        xml,\n        version: newVersion,\n        stateId: existing?.stateId ?? randomUUID(),\n        serverVersion: fromBrowser ? existing?.serverVersion : newVersion,\n        serverXml: fromBrowser ? existing?.serverXml : xml,\n        userEdited: fromBrowser ? existing?.userEdited : false,\n        lastUpdated: new Date(),\n        lastPolled: existing?.lastPolled,\n        // The image of this XML, never an older one's: a write without an\n        // image (AI write, sync reply) leaves none until the browser sends\n        // it, unless it is the same XML\n        svg:\n            svg ||\n            (existing && existing.xml === xml ? existing.svg : undefined),\n        syncRequested: undefined, // Clear sync request when browser pushes state\n        exportFormat: existing?.exportFormat, // Preserve pending export request\n        exportXml: existing?.exportXml, // Preserve pending projection\n        exportOptions: existing?.exportOptions,\n        exportId: existing?.exportId,\n        exportData: existing?.exportData, // Preserve export result\n        selectionId: existing?.selectionId, // Preserve pending selection request\n        selection: existing?.selection,\n    })\n    log.debug(`State updated: session=${sessionId}, version=${newVersion}`)\n    // An AI write or a restore; the browser's pushes are told apart where\n    // they arrive (a sync reply is no change)\n    if (notify && !fromBrowser && existing?.xml !== xml) {\n        markFileChanged(sessionId)\n    }\n    if (notify) stateListener?.(sessionId, xml)\n    return newVersion\n}\n\n/**\n * Keep the session's diagram in History before a write replaces it.\n * Nothing to keep when the browser saved no change of the user's since the\n * last server write and History ends with that write: the state is that\n * write, or draw.io's own copy of it from a sync (other text, same diagram).\n */\nexport function keepInHistory(sessionId: string, xml: string, svg = \"\"): void {\n    const state = stateStore.get(sessionId)\n    const last = getHistory(sessionId).at(-1)\n    if (state && !state.userEdited && last && last.xml === state.serverXml) {\n        return\n    }\n    addHistory(sessionId, xml, svg, state?.userEdited ? \"user\" : undefined)\n}\n\n/**\n * Ask the browser bridge to export the current diagram as png/svg.\n *\n * When `projectionXml` is given (a single-page <mxfile>), the bridge loads it\n * first, waits for draw.io's own load event, exports, then reloads the\n * session's real document — so a page-targeted export never mutates the\n * canonical session state and needs no fixed-delay guessing on the server.\n *\n * Returns false when the session is unknown. Callers should then poll\n * `getState(sessionId)?.exportData` for the result.\n */\nexport function requestExport(\n    sessionId: string,\n    format: ExportFormat,\n    projectionXml?: string,\n    options?: ExportOptions,\n): boolean {\n    const state = stateStore.get(sessionId)\n    if (!state) return false\n    state.exportData = undefined\n    state.exportXml = projectionXml\n    state.exportOptions = options\n    state.exportFormat = format\n    // The browser sends this back with the result, so a late result of an\n    // export that timed out is not taken for this one. Random rather than\n    // counted: a counter restarts with the process, and the page retries a\n    // result refused with 403 against the process that took over the port\n    state.exportId = randomUUID()\n    return true\n}\n\nexport function requestSync(sessionId: string): boolean {\n    const state = stateStore.get(sessionId)\n    if (state) {\n        state.syncRequested = Date.now()\n        log.debug(`Sync requested for session=${sessionId}`)\n        return true\n    }\n    log.debug(`Sync requested for non-existent session=${sessionId}`)\n    return false\n}\n\nexport async function waitForSync(\n    sessionId: string,\n    timeoutMs = 3000,\n): Promise<boolean> {\n    const start = Date.now()\n    while (Date.now() - start < timeoutMs) {\n        const state = stateStore.get(sessionId)\n        if (!state?.syncRequested) return true // Sync completed\n        await new Promise((r) => setTimeout(r, 100))\n    }\n    log.warn(`Sync timeout for session=${sessionId}`)\n    return false // Timeout\n}\n\n/**\n * Ask the preview tab which cells the user has selected (the get_selection\n * tool). Answered through the poll like an export: the tab sees selectionId\n * in GET /api/state and POSTs its reading with that id. Returns false when\n * the session is unknown.\n */\nexport function requestSelection(sessionId: string): boolean {\n    const state = stateStore.get(sessionId)\n    if (!state) return false\n    state.selection = undefined\n    // Random, as exportId: a late answer to an earlier request, or one meant\n    // for the process that had this port before, is not taken for this one\n    state.selectionId = randomUUID()\n    return true\n}\n\n/** The tab's answer to the pending selection request, or null in time */\nexport async function waitForSelection(\n    sessionId: string,\n    timeoutMs = 10000,\n): Promise<SelectionAnswer | null> {\n    const start = Date.now()\n    let answer: SelectionAnswer | undefined\n    while (Date.now() - start < timeoutMs) {\n        // Re-read the store entry each tick: setState replaces it\n        answer = stateStore.get(sessionId)?.selection\n        if (answer) break\n        await new Promise((r) => setTimeout(r, 100))\n    }\n    const state = stateStore.get(sessionId)\n    if (state) {\n        state.selection = undefined\n        state.selectionId = undefined\n    }\n    if (!answer) log.warn(`Selection timeout for session=${sessionId}`)\n    return answer ?? null\n}\n\n// One selection slot per session, as the export slot: overlapping\n// get_selection calls take turns instead of replacing each other's request\nlet selectionQueue: Promise<unknown> = Promise.resolve()\n\n/** requestSelection + waitForSelection, one call at a time; null when the\n * session is unknown or the tab does not answer in time */\nexport function readSelection(\n    sessionId: string,\n    timeoutMs = 10000,\n): Promise<SelectionAnswer | null> {\n    const run = selectionQueue.then(() => {\n        if (!requestSelection(sessionId)) return null\n        return waitForSelection(sessionId, timeoutMs)\n    })\n    selectionQueue = run.catch(() => {})\n    return run\n}\n\n/**\n * What the version cards depend on: History's entries (their count and the\n * newest id) and the entry the canvas shows. The shell reads History again\n * only when this changes, so a hand edit (a new version, the same History)\n * costs no download of every entry\n */\nfunction historyKeyOf(sessionId: string, state?: SessionState): string {\n    const history = getHistory(sessionId)\n    const current =\n        state && history.length > 0\n            ? currentEntryId(sessionId, state.xml)\n            : null\n    return `${history.length}:${history.at(-1)?.id ?? -1}:${current}`\n}\n\n/** POST /api/state with a selection: the tab's answer to requestSelection */\nfunction handleSelectionResult(\n    sessionId: string,\n    data: { selectionId?: unknown; selection?: unknown },\n): void {\n    const state = stateStore.get(sessionId)\n    // Only the pending request's answer (none pending: none is taken)\n    if (!state?.selectionId || data.selectionId !== state.selectionId) {\n        log.debug(`Ignored a late selection answer for session=${sessionId}`)\n        return\n    }\n    const answer = parseSelectionAnswer(data.selection)\n    if (!answer) return\n    state.selection = answer\n    state.selectionId = undefined\n    log.debug(`Selection received for session=${sessionId}`)\n}\n\nexport function startHttpServer(port = 6002): Promise<number> {\n    return new Promise((resolve, reject) => {\n        if (server) {\n            resolve(serverPort)\n            return\n        }\n\n        serverPort = port\n        server = http.createServer(handleRequest)\n\n        server.on(\"error\", (err: NodeJS.ErrnoException) => {\n            if (err.code === \"EADDRINUSE\") {\n                if (port >= MAX_PORT) {\n                    reject(\n                        new Error(\n                            `No available ports in range 6002-${MAX_PORT}`,\n                        ),\n                    )\n                    return\n                }\n                log.info(`Port ${port} in use, trying ${port + 1}`)\n                server = null\n                startHttpServer(port + 1)\n                    .then(resolve)\n                    .catch(reject)\n            } else {\n                reject(err)\n            }\n        })\n\n        server.listen(port, \"127.0.0.1\", () => {\n            serverPort = port\n            log.info(`HTTP server running on http://localhost:${port}`)\n            if (!EXTERNAL_DRAWIO && drawioDir === null) {\n                log.warn(\n                    \"No bundled draw.io (dist/drawio missing); the preview loads it from embed.diagrams.net\",\n                )\n            }\n            if (PREVIEW_UI === \"shell\" && activePreviewUi() === \"classic\") {\n                log.warn(\n                    \"The canvas shell is not built (dist/shell missing); start_session opens the classic page\",\n                )\n            }\n            resolve(port)\n        })\n    })\n}\n\nfunction stopHttpServer(): void {\n    if (server) {\n        server.close()\n        server = null\n    }\n}\n\nfunction cleanupExpiredSessions(): void {\n    const now = Date.now()\n    for (const [sessionId, state] of stateStore) {\n        const lastActive = Math.max(\n            state.lastUpdated.getTime(),\n            state.lastPolled ?? 0,\n        )\n        if (now - lastActive > SESSION_TTL) {\n            stateStore.delete(sessionId)\n            clearHistory(sessionId)\n            sessionFiles.delete(sessionId)\n            changeCounts.delete(sessionId)\n            log.info(`Cleaned up expired session: ${sessionId}`)\n        }\n    }\n}\n\nconst cleanupIntervalId = setInterval(cleanupExpiredSessions, 5 * 60 * 1000)\n\nexport function shutdown(): void {\n    clearInterval(cleanupIntervalId)\n    stopHttpServer()\n}\n\nexport function getServerPort(): number {\n    return serverPort\n}\n\nfunction handleRequest(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n): void {\n    // A bad request must never take down the MCP process\n    try {\n        routeRequest(req, res)\n    } catch (err) {\n        log.error(\"HTTP request failed:\", err)\n        if (!res.headersSent) res.writeHead(500)\n        res.end()\n    }\n}\n\n// Serve only requests addressed to localhost or the explicit preview origin,\n// sent by the preview page\n// itself (Origin is the address it was opened at, the Host) or by a\n// non-browser client (no Origin header). This blocks DNS rebinding, other\n// websites, and pages on other localhost ports, whose plain text POSTs need\n// no CORS preflight.\nfunction isLocalRequest(req: http.IncomingMessage): boolean {\n    const host = req.headers.host ?? \"\"\n    const origin = req.headers.origin\n    if (PREVIEW_ORIGIN && host === new URL(PREVIEW_ORIGIN).host) {\n        return origin === undefined || origin === PREVIEW_ORIGIN\n    }\n    return (\n        /^(localhost|127\\.0\\.0\\.1)(:\\d+)?$/.test(host) &&\n        (origin === undefined || origin === `http://${host}`)\n    )\n}\n\nfunction routeRequest(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n): void {\n    let url: URL\n    try {\n        url = new URL(req.url || \"/\", `http://localhost:${serverPort}`)\n    } catch {\n        // e.g. \"//\" is not a valid URL path\n        res.writeHead(400)\n        res.end(\"Bad Request\")\n        return\n    }\n\n    if (!isLocalRequest(req)) {\n        res.writeHead(403)\n        res.end(\"Forbidden\")\n        return\n    }\n\n    const requestOrigin = req.headers.origin\n    if (\n        requestOrigin === `http://localhost:${serverPort}` ||\n        (PREVIEW_ORIGIN !== undefined && requestOrigin === PREVIEW_ORIGIN)\n    ) {\n        res.setHeader(\"Access-Control-Allow-Origin\", requestOrigin)\n        res.setHeader(\"Access-Control-Allow-Methods\", \"GET, POST, OPTIONS\")\n        res.setHeader(\n            \"Access-Control-Allow-Headers\",\n            \"Content-Type, X-Drawio-Token\",\n        )\n    }\n\n    if (req.method === \"OPTIONS\") {\n        res.writeHead(204)\n        res.end()\n        return\n    }\n\n    if (url.pathname.startsWith(\"/drawio/\")) {\n        serveStaticFile(\n            req,\n            res,\n            drawioDir,\n            url.pathname.slice(\"/drawio/\".length),\n            drawioVersion,\n        )\n        return\n    }\n\n    if (url.pathname === \"/shell\") {\n        res.writeHead(302, { Location: `/shell/${url.search}` })\n        res.end()\n        return\n    }\n    if (url.pathname.startsWith(\"/shell/\")) {\n        const rest = url.pathname.slice(\"/shell/\".length)\n        if (rest === \"\" || rest === \"index.html\") {\n            servePage(req, res, url, \"/shell/\", getShellPage)\n        } else {\n            serveStaticFile(req, res, shellDir, rest, PACKAGE_VERSION)\n        }\n        return\n    }\n\n    if (\n        url.pathname.startsWith(\"/api/\") &&\n        req.headers[\"x-drawio-token\"] !== API_TOKEN\n    ) {\n        res.writeHead(403)\n        res.end(\"Forbidden\")\n        return\n    }\n\n    if (url.pathname === \"/\" || url.pathname === \"/index.html\") {\n        servePage(req, res, url, \"/\", getHtmlPage)\n    } else if (url.pathname === \"/api/state\") {\n        handleStateApi(req, res, url)\n    } else if (url.pathname === \"/api/history\") {\n        handleHistoryApi(req, res, url)\n    } else if (url.pathname === \"/api/restore\") {\n        handleRestoreApi(req, res)\n    } else if (url.pathname === \"/api/history-svg\") {\n        handleHistorySvgApi(req, res)\n    } else {\n        res.writeHead(404)\n        res.end(\"Not Found\")\n    }\n}\n\n/**\n * A preview page (the classic one at \"/\", the shell at \"/shell/\") for the\n * session in ?mcp=<id>; without one, the most recent session's.\n */\nfunction servePage(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n    url: URL,\n    pagePath: string,\n    render: (sessionId: string) => string | null,\n): void {\n    if (req.method !== \"GET\" && req.method !== \"HEAD\") {\n        res.writeHead(405)\n        res.end(\"Method Not Allowed\")\n        return\n    }\n    const sessionId = url.searchParams.get(\"mcp\") || \"\"\n    if (sessionId && !isValidSessionId(sessionId)) {\n        // A chat app can make the text after a bare link part of it\n        // (\"?mcp=mcp-abc。Next sentence\"): go to the id it starts with\n        const start = sessionId.match(/^mcp-[a-z0-9-]{1,64}/)?.[0]\n        if (start) {\n            res.writeHead(302, { Location: `${pagePath}?mcp=${start}` })\n            res.end()\n            return\n        }\n        res.writeHead(400)\n        res.end(\"Invalid session id\")\n        return\n    }\n\n    // Auto-redirect to most recent session if no sessionId provided\n    if (!sessionId) {\n        const recentSessionId = getMostRecentSessionId()\n        if (recentSessionId) {\n            res.writeHead(302, {\n                Location: `${pagePath}?mcp=${encodeURIComponent(recentSessionId)}`,\n            })\n            res.end()\n            return\n        }\n    }\n\n    const html = render(sessionId)\n    if (html === null) {\n        res.writeHead(404, { \"Content-Type\": \"text/plain; charset=utf-8\" })\n        res.end(\n            \"The canvas shell is not built (dist/shell is missing); run npm run build in packages/mcp-server\",\n        )\n        return\n    }\n    ensureSessionStateInitialized(sessionId)\n\n    // The page holds this process's token: never served from a cache\n    res.writeHead(200, {\n        \"Content-Type\": \"text/html; charset=utf-8\",\n        \"Cache-Control\": \"no-store\",\n        ...htmlSecurityHeaders(),\n    })\n    res.end(req.method === \"HEAD\" ? undefined : html)\n}\n\nfunction handleStateApi(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n    url: URL,\n): void {\n    if (req.method === \"GET\") {\n        const sessionId = url.searchParams.get(\"sessionId\")\n        if (!sessionId) {\n            res.writeHead(400, { \"Content-Type\": \"application/json\" })\n            res.end(JSON.stringify({ error: \"sessionId required\" }))\n            return\n        }\n        ensureSessionStateInitialized(sessionId)\n        const state = stateStore.get(sessionId)\n        // Polling counts as activity, so a session stays alive while its\n        // tab is open\n        if (state) state.lastPolled = Date.now()\n        res.writeHead(200, { \"Content-Type\": \"application/json\" })\n        res.end(\n            JSON.stringify({\n                xml: state?.xml || null,\n                version: state?.version || 0,\n                stateId: state?.stateId ?? null,\n                blank: !!state?.blank,\n                syncRequested: !!state?.syncRequested,\n                exportFormat: state?.exportFormat || null,\n                exportXml: state?.exportXml || null,\n                exportOptions: state?.exportOptions || null,\n                exportId: state?.exportId ?? null,\n                selectionId: state?.selectionId ?? null,\n                historyKey: historyKeyOf(sessionId, state),\n                file: sessionFiles.get(sessionId)?.path ?? null,\n                fileChanged: sessionFiles.get(sessionId)?.changed ?? false,\n            }),\n        )\n    } else if (req.method === \"POST\") {\n        readBody(req, res, (body) => {\n            try {\n                const data = JSON.parse(body)\n                const { sessionId } = data\n                if (!sessionId || !isValidSessionId(sessionId)) {\n                    res.writeHead(400, { \"Content-Type\": \"application/json\" })\n                    res.end(\n                        JSON.stringify({ error: \"valid sessionId required\" }),\n                    )\n                    return\n                }\n\n                // Browser is returning export data (png/svg)\n                if (data.exportData !== undefined) {\n                    const state = stateStore.get(sessionId)\n                    if (state && data.exportId === state.exportId) {\n                        state.exportData = data.exportData\n                        state.exportFormat = undefined\n                        state.exportXml = undefined\n                        state.exportOptions = undefined\n                        state.exportId = undefined\n                        log.debug(\n                            `Export data received for session=${sessionId}`,\n                        )\n                    } else if (state) {\n                        log.debug(\n                            `Ignored a late export result for session=${sessionId}`,\n                        )\n                    }\n                    res.writeHead(200, { \"Content-Type\": \"application/json\" })\n                    res.end(JSON.stringify({ success: true }))\n                    return\n                }\n\n                // The tab is answering a selection request (get_selection)\n                if (data.selection !== undefined) {\n                    handleSelectionResult(sessionId, data)\n                    res.writeHead(200, { \"Content-Type\": \"application/json\" })\n                    res.end(JSON.stringify({ success: true }))\n                    return\n                }\n\n                // A push can come before the tab's first poll after a\n                // restart: recover the saved file first, so it is compared\n                // with that and never overwrites it unseen\n                ensureSessionStateInitialized(sessionId)\n                const current = stateStore.get(sessionId)\n\n                // A tab of this version names the state its push is based\n                // on. Another state (the server lost the one it knew, or\n                // the tab has not polled yet): refused, and the tab's next\n                // poll decides whose diagram wins.\n                if (current && \"stateId\" in data) {\n                    if (data.stateId !== current.stateId) {\n                        res.writeHead(409, {\n                            \"Content-Type\": \"application/json\",\n                        })\n                        res.end(\n                            JSON.stringify({ error: \"Session was recreated\" }),\n                        )\n                        return\n                    }\n                    // What a recovering tab showed: kept in history only\n                    if (data.source === \"recover\") {\n                        const saved =\n                            typeof data.xml === \"string\" &&\n                            !!data.xml &&\n                            data.xml !== current.xml\n                        if (saved) {\n                            addHistory(\n                                sessionId,\n                                data.xml,\n                                data.svg || \"\",\n                                \"recover\",\n                            )\n                            // Saved with the History, as after any change\n                            stateListener?.(sessionId, current.xml)\n                        }\n                        res.writeHead(409, {\n                            \"Content-Type\": \"application/json\",\n                        })\n                        res.end(\n                            JSON.stringify({\n                                error: \"Diagram changed on the server\",\n                                savedToHistory: saved,\n                            }),\n                        )\n                        return\n                    }\n                }\n\n                // The browser edited a version older than the latest AI write\n                // (it has not loaded that write yet). Keep the AI write; the\n                // browser loads it on its next poll. A sync reply is also\n                // stale after a newer write of the browser's own (a user\n                // edit saved while the export ran).\n                if (\n                    typeof data.baseVersion === \"number\" &&\n                    (data.baseVersion < (current?.serverVersion ?? 0) ||\n                        (data.source === \"sync\" &&\n                            data.baseVersion < (current?.version ?? 0)))\n                ) {\n                    let savedToHistory = false\n                    if (data.source === \"sync\") {\n                        // A stale sync reply: the store already holds the\n                        // newer AI write, so the sync is done.\n                        if (current) current.syncRequested = undefined\n                    } else if (typeof data.xml === \"string\" && data.xml) {\n                        // A user edit lost the race with an AI write. Keep\n                        // it in history so the user can restore it.\n                        addHistory(sessionId, data.xml, data.svg || \"\", \"user\")\n                        savedToHistory = true\n                        if (current) stateListener?.(sessionId, current.xml)\n                    }\n                    res.writeHead(409, { \"Content-Type\": \"application/json\" })\n                    res.end(\n                        JSON.stringify({\n                            error: \"Diagram changed on the server\",\n                            savedToHistory,\n                        }),\n                    )\n                    return\n                }\n\n                if (typeof data.xml !== \"string\") {\n                    res.writeHead(400, { \"Content-Type\": \"application/json\" })\n                    res.end(JSON.stringify({ error: \"xml must be a string\" }))\n                    return\n                }\n                const version = setState(sessionId, data.xml, data.svg, true)\n                const saved = stateStore.get(sessionId)\n                if (saved && data.source !== \"sync\") {\n                    saved.userEdited = true\n                    markFileChanged(sessionId)\n                }\n                res.writeHead(200, { \"Content-Type\": \"application/json\" })\n                res.end(\n                    JSON.stringify({\n                        success: true,\n                        version,\n                        historyKey: historyKeyOf(sessionId, saved),\n                    }),\n                )\n            } catch {\n                res.writeHead(400, { \"Content-Type\": \"application/json\" })\n                res.end(JSON.stringify({ error: \"Invalid JSON\" }))\n            }\n        })\n    } else {\n        res.writeHead(405)\n        res.end(\"Method Not Allowed\")\n    }\n}\n\nfunction handleHistoryApi(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n    url: URL,\n): void {\n    if (req.method !== \"GET\") {\n        res.writeHead(405)\n        res.end(\"Method Not Allowed\")\n        return\n    }\n\n    const sessionId = url.searchParams.get(\"sessionId\")\n    if (!sessionId) {\n        res.writeHead(400, { \"Content-Type\": \"application/json\" })\n        res.end(JSON.stringify({ error: \"sessionId required\" }))\n        return\n    }\n\n    // The classic page reads index, id and svg; the shell's version cards\n    // the rest: the document, who made it, which earlier entry it is a copy\n    // of, the state the ids belong to, and the entry the canvas shows\n    const history = getHistory(sessionId)\n    const firstIds = firstCopyIds(sessionId)\n    const state = stateStore.get(sessionId)\n    res.writeHead(200, { \"Content-Type\": \"application/json\" })\n    res.end(\n        JSON.stringify({\n            entries: history.map((entry, i) => ({\n                index: i,\n                id: entry.id,\n                svg: entry.svg,\n                xml: entry.xml,\n                source: entry.source ?? null,\n                firstId: firstIds.get(entry.id),\n            })),\n            count: history.length,\n            stateId: state?.stateId ?? null,\n            currentId: state ? currentEntryId(sessionId, state.xml) : null,\n        }),\n    )\n}\n\n/**\n * Put a History entry back on the canvas (the preview page's Restore button\n * and the restore_version tool). Returns the new version, or null when the\n * entry is unknown.\n */\nexport function restoreHistoryEntry(\n    sessionId: string,\n    entryId: number,\n): number | null {\n    const entry = getHistoryEntry(sessionId, entryId)\n    if (!entry) return null\n\n    // Edits in the browser since the last entry are not in history\n    // yet: keep them, so the restore can be undone\n    // (any state besides a blank page; a cleared document with its\n    // own pages counts)\n    const current = stateStore.get(sessionId)\n    if (\n        current &&\n        contentFingerprint(current.xml) !== contentFingerprint(BLANK_MXFILE)\n    ) {\n        keepInHistory(sessionId, current.xml, current.svg)\n    }\n    const newVersion = setState(sessionId, entry.xml)\n    addHistory(sessionId, entry.xml, entry.svg, \"restore\")\n\n    log.info(`Restored session ${sessionId} to history entry ${entryId}`)\n    return newVersion\n}\n\nfunction handleRestoreApi(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n): void {\n    if (req.method !== \"POST\") {\n        res.writeHead(405)\n        res.end(\"Method Not Allowed\")\n        return\n    }\n\n    readBody(req, res, (body) => {\n        try {\n            const data = JSON.parse(body)\n            const { sessionId, id } = data\n            if (!sessionId || typeof id !== \"number\") {\n                res.writeHead(400, { \"Content-Type\": \"application/json\" })\n                res.end(JSON.stringify({ error: \"sessionId and id required\" }))\n                return\n            }\n            // Picked from the list of a state the server has since lost\n            // (a restart reloads History under new ids), or before the tab\n            // knew the state. A tab of an older version sends none.\n            const current = stateStore.get(sessionId)\n            if (\n                current &&\n                \"stateId\" in data &&\n                data.stateId !== current.stateId\n            ) {\n                res.writeHead(409, { \"Content-Type\": \"application/json\" })\n                res.end(JSON.stringify({ error: \"Session was recreated\" }))\n                return\n            }\n\n            if (restoreHistoryEntry(sessionId, id) === null) {\n                res.writeHead(404, { \"Content-Type\": \"application/json\" })\n                res.end(JSON.stringify({ error: \"Entry not found\" }))\n                return\n            }\n\n            res.writeHead(200, { \"Content-Type\": \"application/json\" })\n            res.end(JSON.stringify({ success: true }))\n        } catch {\n            res.writeHead(400, { \"Content-Type\": \"application/json\" })\n            res.end(JSON.stringify({ error: \"Invalid JSON\" }))\n        }\n    })\n}\n\nfunction handleHistorySvgApi(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n): void {\n    if (req.method !== \"POST\") {\n        res.writeHead(405)\n        res.end(\"Method Not Allowed\")\n        return\n    }\n\n    readBody(req, res, (body) => {\n        try {\n            const { sessionId, svg, stateId, version } = JSON.parse(body)\n            if (!sessionId || !svg) {\n                res.writeHead(400, { \"Content-Type\": \"application/json\" })\n                res.end(JSON.stringify({ error: \"sessionId and svg required\" }))\n                return\n            }\n\n            // The browser took it of the server write it loaded, named by\n            // the state and version. One that arrives after the next server\n            // write, or for a state since lost, is dropped; a browser write\n            // since (a sync reply) leaves that write's image valid.\n            const state = stateStore.get(sessionId)\n            if (\n                state &&\n                state.stateId === stateId &&\n                state.serverVersion === version &&\n                state.serverXml !== undefined\n            ) {\n                updateLastHistorySvg(sessionId, svg, state.serverXml)\n                if (state.xml === state.serverXml) state.svg = svg\n            }\n            res.writeHead(200, { \"Content-Type\": \"application/json\" })\n            res.end(JSON.stringify({ success: true }))\n        } catch {\n            res.writeHead(400, { \"Content-Type\": \"application/json\" })\n            res.end(JSON.stringify({ error: \"Invalid JSON\" }))\n        }\n    })\n}\n\n// Pages may be framed only by this origin, and nothing is content-sniffed.\n// DRAWIO_ALLOW_EMBED=true also lets pages on this machine frame them, so\n// DeepSeek Harness can show the preview in its sidebar browser.\nfunction htmlSecurityHeaders(): Record<string, string> {\n    const ancestors =\n        process.env.DRAWIO_ALLOW_EMBED === \"true\"\n            ? \"'self' localhost:* 127.0.0.1:*\"\n            : \"'self'\"\n    return {\n        \"Content-Security-Policy\": `frame-ancestors ${ancestors}`,\n        \"X-Content-Type-Options\": \"nosniff\",\n    }\n}\n\nconst MIME_TYPES: Record<string, string> = {\n    \".html\": \"text/html; charset=utf-8\",\n    \".js\": \"text/javascript; charset=utf-8\",\n    \".css\": \"text/css; charset=utf-8\",\n    \".svg\": \"image/svg+xml\",\n    \".png\": \"image/png\",\n    \".gif\": \"image/gif\",\n    \".jpg\": \"image/jpeg\",\n    \".jpeg\": \"image/jpeg\",\n    \".woff\": \"font/woff\",\n    \".woff2\": \"font/woff2\",\n    \".ttf\": \"font/ttf\",\n    \".txt\": \"text/plain; charset=utf-8\",\n    \".xml\": \"text/xml; charset=utf-8\",\n    \".json\": \"application/json\",\n    \".ico\": \"image/x-icon\",\n    \".wasm\": \"application/wasm\",\n}\n\n/**\n * GET /drawio/<path> or /shell/<path>: a file of the bundled draw.io copy or\n * of the built shell. `stamp` names the files' version in their ETags.\n */\nfunction serveStaticFile(\n    req: http.IncomingMessage,\n    res: http.ServerResponse,\n    dir: string | null,\n    rawPath: string,\n    stamp: string,\n): void {\n    if (req.method !== \"GET\" && req.method !== \"HEAD\") {\n        res.writeHead(405)\n        res.end(\"Method Not Allowed\")\n        return\n    }\n    let rel: string\n    try {\n        rel = decodeURIComponent(rawPath)\n    } catch {\n        res.writeHead(400)\n        res.end(\"Bad Request\")\n        return\n    }\n    // One normalized path inside the directory; the war's server-side parts\n    // are never served, whatever was extracted\n    const normalized = posix.normalize(rel)\n    const file = dir ? resolve(dir, normalized) : null\n    if (\n        !dir ||\n        !file ||\n        /[\\\\\\0]/.test(rel) ||\n        /(^|\\/)(WEB-INF|META-INF)(\\/|$)/i.test(normalized) ||\n        !file.startsWith(dir + sep)\n    ) {\n        res.writeHead(404)\n        res.end(\"Not Found\")\n        return\n    }\n    let size: number\n    let etag: string\n    try {\n        const stat = statSync(file)\n        if (!stat.isFile()) throw new Error(\"not a file\")\n        size = stat.size\n        etag = `\"${stamp}-${size.toString(16)}-${Math.floor(stat.mtimeMs).toString(16)}\"`\n    } catch {\n        res.writeHead(404)\n        res.end(\"Not Found\")\n        return\n    }\n    // The file names do not change between draw.io versions, so the browser\n    // may keep a copy but asks before using it (a 304 from localhost is\n    // cheap); after a package upgrade the next preview gets the new files\n    const cacheHeaders = {\n        ETag: etag,\n        \"Cache-Control\": \"no-cache\",\n        \"X-Content-Type-Options\": \"nosniff\",\n    }\n    if (req.headers[\"if-none-match\"] === etag) {\n        res.writeHead(304, cacheHeaders)\n        res.end()\n        return\n    }\n    const ext = extname(file).toLowerCase()\n    res.writeHead(200, {\n        ...cacheHeaders,\n        \"Content-Type\": MIME_TYPES[ext] || \"application/octet-stream\",\n        \"Content-Length\": size,\n        ...(ext === \".html\" ? htmlSecurityHeaders() : {}),\n    })\n    if (req.method === \"HEAD\") {\n        res.end()\n        return\n    }\n    // pipeline closes both ends when either fails or goes away (a tab closed\n    // mid-download), so no file handle leaks and no error goes unhandled; a\n    // client that left early is routine, not worth a log line\n    pipeline(createReadStream(file), res, () => {})\n}\n\n/** Where the iframe loads the editor from (without its query) */\nfunction drawioEditorUrl(): string {\n    return isSameOriginDrawio()\n        ? \"/drawio/index.html\"\n        : `${normalizeUrl(DRAWIO_BASE_URL)}/`\n}\n\n// The preview page lives in src/preview (the build copies it to dist/preview)\nconst PREVIEW_DIR = join(HERE, \"preview\")\nlet previewTemplate: string | null = null\n\nfunction loadPreviewTemplate(): string {\n    if (!previewTemplate) {\n        const read = (file: string) =>\n            readFileSync(join(PREVIEW_DIR, file), \"utf-8\")\n        previewTemplate = read(\"index.html\")\n            .replace(\"{{CSS}}\", () => read(\"preview.css\"))\n            .replace(\"{{SCRIPT}}\", () => read(\"preview.js\"))\n    }\n    return previewTemplate\n}\n\n/** JSON that is safe inside a <script> element (\"<\" escaped) */\nconst scriptJson = (value: unknown) =>\n    JSON.stringify(value).replace(/</g, \"\\\\u003c\")\n\n/**\n * The editor settings the host config fixes: theme (DRAWIO_UI), language\n * (DRAWIO_LANG) and dark mode (DRAWIO_DARK). ui and lang are \"\" unless set,\n * because draw.io hides its Extras > Language / Theme submenu once they\n * are given.\n */\nfunction hostDrawioSettings(env: NodeJS.ProcessEnv): {\n    ui: string\n    lang: string\n    dark: \"dark\" | \"light\" | \"auto\"\n} {\n    const ui = (env.DRAWIO_UI ?? \"\").toLowerCase()\n    const dark = (env.DRAWIO_DARK ?? \"\").toLowerCase()\n    const lang = toDrawioLang(env.DRAWIO_LANG ?? \"\")\n    return {\n        ui: isDrawioTheme(ui) ? ui : \"\",\n        lang: /^[a-z]{2,3}(-[a-z]{2,4})?$/.test(lang) ? lang : \"\",\n        dark: [\"1\", \"true\", \"dark\"].includes(dark)\n            ? \"dark\"\n            : [\"0\", \"false\", \"light\"].includes(dark)\n              ? \"light\"\n              : // draw.io takes ui=dark as dark mode only when no dark\n                // parameter is present, and the pages always send one\n                !dark && ui === \"dark\"\n                ? \"dark\"\n                : \"auto\",\n    }\n}\n\n/**\n * The configurable tail of the classic page's draw.io iframe query: dark\n * mode, and the language and theme when the host config fixes them.\n */\nexport function drawioEmbedParams(\n    env: NodeJS.ProcessEnv = process.env,\n): string {\n    const settings = hostDrawioSettings(env)\n    const params = new URLSearchParams()\n    params.set(\n        \"dark\",\n        settings.dark === \"auto\"\n            ? \"auto\"\n            : settings.dark === \"dark\"\n              ? \"1\"\n              : \"0\",\n    )\n    if (settings.lang) params.set(\"lang\", settings.lang)\n    if (settings.ui) params.set(\"ui\", settings.ui)\n    return params.toString()\n}\n\n/**\n * What the shell page gets as window.__MCP_CONFIG__ (shell/runtime-config.ts\n * reads it): the session, the API token, where draw.io comes from and the\n * host's editor settings.\n */\nexport function shellConfig(\n    sessionId: string,\n    env: NodeJS.ProcessEnv = process.env,\n): Record<string, string> {\n    const settings = hostDrawioSettings(env)\n    return {\n        sessionId,\n        token: API_TOKEN,\n        apiBase: \"/api\",\n        drawioBaseUrl: drawioEditorUrl(),\n        drawioUi: settings.ui,\n        drawioLang: settings.lang,\n        drawioDark: settings.dark,\n        lang: env.DRAWIO_LANG ?? \"\",\n        version: PACKAGE_VERSION,\n    }\n}\n\n/** The shell page, or null when the shell is not built */\nfunction getShellPage(sessionId: string): string | null {\n    if (!shellDir) return null\n    const template = readFileSync(join(shellDir, \"index.html\"), \"utf8\")\n    return template.replace(\"{{CONFIG_JSON}}\", () =>\n        scriptJson(shellConfig(sessionId)),\n    )\n}\n\nfunction getHtmlPage(sessionId: string): string {\n    return (\n        loadPreviewTemplate()\n            .replace(\"{{SESSION_BADGE}}\", () =>\n                sessionId\n                    ? `<span class=\"session\">${sessionId.slice(-8)}</span>`\n                    : \"\",\n            )\n            .replaceAll(\"{{DISABLED}}\", sessionId ? \"\" : \"disabled\")\n            .replace(\"{{DRAWIO_URL}}\", () => drawioEditorUrl())\n            .replace(\"{{DRAWIO_PARAMS}}\", () => drawioEmbedParams())\n            .replace(\"{{SESSION_JSON}}\", () => scriptJson(sessionId))\n            // Same origin: the page fills in its own origin\n            .replace(\"{{ORIGIN_JSON}}\", () =>\n                scriptJson(isSameOriginDrawio() ? \"\" : DRAWIO_ORIGIN),\n            )\n            .replace(\"{{TOKEN_JSON}}\", () => scriptJson(API_TOKEN))\n    )\n}\n"
    },
    {
      "path": "packages/mcp-server/src/index.ts",
      "content": "#!/usr/bin/env node\n/**\n * MCP Server for Next AI Draw.io\n *\n * Enables AI agents (Claude Desktop, Cursor, etc.) to generate and edit\n * draw.io diagrams with real-time browser preview.\n *\n * Uses an embedded HTTP server - no external dependencies required.\n *\n * Multi-page support\n * ------------------\n * The canonical in-memory shape for the session XML is always an <mxfile>\n * containing one or more <diagram> pages. Legacy callers that pass a bare\n * <mxGraphModel> to create_new_diagram are auto-wrapped into a single-page\n * mxfile. All page-targeting parameters (page_id / page_name / page_index)\n * on edit_diagram, get_diagram, and export_diagram are optional and default\n * to the first page. See packages/mcp-server/src/pages.ts for the helper\n * surface.\n */\n\nimport { spawn } from \"node:child_process\"\nimport { mkdir, readFile, stat, writeFile } from \"node:fs/promises\"\nimport { createRequire } from \"node:module\"\nimport { dirname, resolve } from \"node:path\"\nimport {\n    McpServer,\n    type ToolCallback,\n} from \"@modelcontextprotocol/sdk/server/mcp.js\"\nimport { StdioServerTransport } from \"@modelcontextprotocol/sdk/server/stdio.js\"\nimport type { ZodRawShapeCompat } from \"@modelcontextprotocol/sdk/server/zod-compat.js\"\nimport type {\n    CallToolResult,\n    ToolAnnotations,\n} from \"@modelcontextprotocol/sdk/types.js\"\nimport open from \"open\"\nimport { z } from \"zod\"\nimport { foldCells } from \"./compact-cells.ts\"\nimport {\n    customInstructionsPath,\n    guideWithCustomInstructions,\n} from \"./custom-instructions.ts\"\nimport type { DiagramOperation } from \"./diagram-operations.ts\"\nimport { installDomPolyfill } from \"./dom.ts\"\nimport { DRAWING_GUIDE } from \"./drawing-guide.ts\"\nimport { editDiagram, targetPageXml } from \"./edit-diagram.ts\"\nimport {\n    checkEditGate,\n    contentFingerprint,\n    countChanges,\n    describeChanges,\n    markPageSeen,\n} from \"./edit-gate.ts\"\nimport { imageRefNote, restoreImageData } from \"./embedded-images.ts\"\nimport { createExclusive } from \"./exclusive.ts\"\nimport {\n    addHistory,\n    getHistory,\n    type HistoryEntry,\n    type HistorySource,\n    isInHistory,\n    otherVersions,\n} from \"./history.ts\"\nimport {\n    activePreviewUi,\n    changeCount,\n    DRAWIO_BASE_URL,\n    type ExportFormat,\n    type ExportOptions,\n    getServerPort,\n    getState,\n    isSameOriginDrawio,\n    keepInHistory,\n    onSessionRecreate,\n    onStateChange,\n    PREVIEW_UI,\n    previewUrl,\n    readSelection,\n    requestExport,\n    requestSync,\n    restoreHistoryEntry,\n    restoreSavedSession,\n    setSessionFile,\n    setState,\n    shutdown,\n    startHttpServer,\n    waitForSync,\n} from \"./http-server.ts\"\nimport { parseDrawioFileContent } from \"./load-diagram.ts\"\nimport { log } from \"./logger.ts\"\nimport { prepareNewDiagram, prepareNewModel } from \"./new-diagram.ts\"\nimport {\n    addPageToDoc,\n    BLANK_MXFILE,\n    deletePageFromDoc,\n    findPageElement,\n    hasCells,\n    hasPageSelector,\n    listPagesFromDoc,\n    normalizeToMxfile,\n    type PageSelector,\n    parseMxfile,\n    projectPage,\n    renamePageInDoc,\n    serializeMxfile,\n} from \"./pages.ts\"\nimport { Autosaver, defaultDataDir, expandHome } from \"./persistence.ts\"\nimport { describeSelection } from \"./selection.ts\"\nimport { getShapeLibrary, SHAPE_LIBRARY_LIST } from \"./shape-library.ts\"\nimport { XML_REFERENCE } from \"./xml-reference.ts\"\n\n// DOMParser/XMLSerializer globals for the XML helpers (Node has neither)\ninstallDomPolyfill()\n\n// Server configuration\nconst config = {\n    port: parseInt(process.env.PORT || \"6002\", 10),\n    // Attach a screenshot to every create_new_diagram and edit_diagram\n    // result unless the call says otherwise\n    autoScreenshot: process.env.DRAWIO_AUTO_SCREENSHOT === \"true\",\n}\n\n// Keep each session's latest diagram and its History on disk, so they\n// survive this process\nconst autosaver = new Autosaver(defaultDataDir(), undefined, undefined, (id) =>\n    getHistory(id),\n)\nonStateChange((sessionId, xml) => autosaver.schedule(sessionId, xml))\nonSessionRecreate((sessionId) => {\n    const saved = autosaver.load(sessionId)\n    if (!saved) return null\n    // A file draw.io saved (compressed pages) comes back as plain XML, as\n    // with load_diagram\n    const loaded = parseDrawioFileContent(saved)\n    // History comes back with the diagram (addHistory drops consecutive\n    // duplicates)\n    for (const e of autosaver.loadHistory(sessionId)) {\n        addHistory(sessionId, e.xml, \"\", e.source)\n    }\n    return loaded.ok ? loaded.xml : saved\n})\n\n// A one-page view that does not count for the whole document (edit-gate.ts)\nconst OTHER_PAGES_UNSEEN =\n    \"You have not seen the other pages in their current state.\"\n\n// The preview outlines what a write changed (lib/drawio/editor-bridge.ts),\n// which the model's own screenshots never show\nconst OUTLINE_NOTE =\n    \"The preview outlines the changed cells for a few seconds on the page that changed. The outline is not part of the diagram and never appears in exports or screenshots; never edit the diagram to remove it.\"\n// The classic preview page (DRAWIO_PREVIEW_UI=classic) draws no outline\nconst outlineNote = () => (PREVIEW_UI === \"classic\" ? \"\" : OUTLINE_NOTE)\n\n// get_diagram shows plain cells the way the model writes them (foldCells)\nconst COMPACT_NOTE =\n    \"Plain shapes are in compact form: x, y, w and h on the mxCell stand for its mxGeometry. edit_diagram and add_page take this form as it is.\"\n\n/**\n * The browser's state of a session. After it expired (or the process\n * restarted) the saved file comes back first, so a tool never builds on an\n * older copy and then overwrites the file. Call it before requestSync or\n * requestExport, which need the state.\n */\nfunction sessionState(sessionId: string) {\n    restoreSavedSession(sessionId)\n    return getState(sessionId)\n}\n\n// Session state (single session for simplicity)\ntype Session = {\n    id: string\n    xml: string\n    // The exact state-store XML the model last saw (get_diagram) or wrote\n    // itself (create/edit/page CRUD). The store only changes on server\n    // writes or browser pushes (user autosave / sync), so edit_diagram can\n    // detect unseen user edits by comparing the live store against this.\n    // Empty = no diagram context established yet.\n    lastSeenXml: string\n}\nlet currentSession: Session | null = null\n\nconst NO_SESSION = \"No active session. Please call start_session first.\"\n\n/** The session of a tool registered with needsSession, checked before it ran */\nfunction activeSession(): Session {\n    if (!currentSession) throw new Error(NO_SESSION)\n    return currentSession\n}\n\n/** A tool result of one text */\nconst ok = (text: string) => ({ content: [{ type: \"text\" as const, text }] })\n\n/** A tool error; every tool reports its errors with this prefix */\nconst fail = (text: string) => ({\n    content: [{ type: \"text\" as const, text: `Error: ${text}` }],\n    isError: true as const,\n})\n\n// Create MCP server. The version reported in the MCP handshake is read from\n// package.json so it can never drift from the published npm version again\n// (it sat hardcoded at stale values for most of this package's history).\n// Both src/ (tsx dev) and dist/ (published build) live one level below the\n// package root, so the relative path works in either runtime.\nconst require = createRequire(import.meta.url)\nconst packageVersion: string = require(\"../package.json\").version\n\n// Hosts truncate instructions (Claude Code at 2,048 characters) and may show\n// only the first 512, so the essentials come first. The full rules are in\n// DRAWING_GUIDE, returned by start_session.\nconst INSTRUCTIONS = `next-ai-drawio creates and edits draw.io diagrams and shows them live in a browser preview, where the user can also edit them by hand. Use it for every change to a .drawio or .drawio.svg file too: load_diagram the file, edit with edit_diagram, then export_diagram to the same path; never write its XML yourself.\n\nStart with start_session: it opens the preview and its result contains the drawing guide (layout, edge routing and style rules). Follow the guide when drawing; call get_drawing_guide if it is no longer in your context.\n\nBefore using cloud or icon shapes (AWS, Azure, GCP, Kubernetes, Cisco, BPMN...), call get_shape_library and use the exact style names it returns. Never guess icon style names.\n\nTo draw from a file, image or web page, read it yourself first; the server only receives XML.\n\nAfter drawing or heavily editing a complex diagram, pass screenshot: true on that create_new_diagram or edit_diagram call (or call screenshot_diagram) to see the result, and fix overlapping shapes and edges that cross shapes.\n\nTools:\n- create_new_diagram: draw a new diagram, replacing the whole document. Send only the mxCell elements of one page (the server adds the wrapper and root cells), or a full <mxfile> for several pages.\n- edit_diagram: add, update or delete cells of an existing page by id. All-or-nothing; a rejected call includes the current XML so you can retry; also used to draw a large diagram in parts.\n- get_diagram: read the current XML, including the user's manual edits.\n- get_selection: the cells the user has selected in the preview, when they say \"this box\" or \"these arrows\".\n- screenshot_diagram: see the rendered diagram as an image.\n- load_diagram, export_diagram: open or save .drawio or .drawio.svg files and export .png or .svg. Use absolute paths.\n- list_saved_diagrams: diagrams saved by earlier sessions; continue one with start_session session_id=<id>.\n- list_pages, add_page, rename_page, delete_page: manage pages (tabs).\n- restore_version: undo; go back to an earlier version of the diagram.`\n\nconst server = new McpServer(\n    {\n        name: \"next-ai-drawio\",\n        version: packageVersion,\n    },\n    { instructions: INSTRUCTIONS },\n)\n\n// The tools that write the diagram, and start_session, run one at a time:\n// two writes at once would both build on the same document, and the second\n// would drop the first one's change. start_session in the queue keeps a\n// session switch from landing in the middle of a write.\nconst exclusive = createExclusive()\n\n/**\n * Register a tool. The handler returns its result or throws: an exception\n * comes back as a tool error (the SDK would report it too, without the\n * \"Error: \" prefix and the log line). With needsSession the handler runs\n * only when a session is active, so it can take activeSession() for\n * granted; write puts it in the queue above.\n */\nfunction registerTool<Args extends ZodRawShapeCompat | undefined = undefined>(\n    name: string,\n    config: {\n        title?: string\n        description?: string\n        inputSchema?: Args\n        annotations?: ToolAnnotations\n    },\n    handler: ToolCallback<Args>,\n    { write = false, needsSession = false } = {},\n) {\n    const run = async (...args: unknown[]) => {\n        if (needsSession && !currentSession) return fail(NO_SESSION)\n        try {\n            return await (handler as (...a: unknown[]) => unknown)(...args)\n        } catch (error) {\n            const message =\n                error instanceof Error ? error.message : String(error)\n            log.error(`${name} failed:`, message)\n            return fail(message)\n        }\n    }\n    server.registerTool(\n        name,\n        config,\n        (write ? exclusive(run) : run) as ToolCallback<Args>,\n    )\n}\n\n// Shared Zod schema fragment for page-targeting parameters.\n// Every multi-page-aware tool reuses these three optional fields so the LLM\n// learns one consistent interface.\nconst pageSelectorSchema = {\n    page_id: z\n        .string()\n        .min(1)\n        .optional()\n        .describe(\n            \"Target a page by its id (as returned by list_pages or add_page). Wins over page_name and page_index when multiple are set.\",\n        ),\n    page_name: z\n        .string()\n        .min(1)\n        .optional()\n        .describe(\n            'Target a page by its display name (e.g. \"CNN\"). Used only when page_id is not set.',\n        ),\n    page_index: z\n        .number()\n        .int()\n        .nonnegative()\n        .optional()\n        .describe(\n            \"Target a page by its 0-based tab index. Used only when page_id and page_name are not set.\",\n        ),\n}\n\n// The optional screenshot of create_new_diagram and edit_diagram\nconst screenshotSchema = z\n    .boolean()\n    .optional()\n    .describe(\n        \"Also return a PNG of the result so you can check it for overlaps and edges crossing shapes. Needs the preview tab open and in front; adds 2 to 10 s. Default: the DRAWIO_AUTO_SCREENSHOT environment variable.\",\n    )\n\n/** Format a selector for human-readable error messages. */\nfunction describeSelector(s: PageSelector): string {\n    if (s.page_id) return `id=\"${s.page_id}\"`\n    if (s.page_name) return `name=\"${s.page_name}\"`\n    if (s.page_index !== undefined) return `index=${s.page_index}`\n    return \"first page\"\n}\n\n/** One line of pages for the tool results: index, id, name and cell count */\nfunction describePages(xml: string, empty = \"no pages parsed\"): string {\n    const doc = parseMxfile(xml)\n    const pages = doc ? listPagesFromDoc(doc) : []\n    return pages.length > 0\n        ? `Pages (${pages.length}): ${pages.map((p) => `[${p.index}] id=${p.id} name=\"${p.name}\" cells=${p.cellCount}`).join(\" | \")}`\n        : empty\n}\n\n/**\n * Take the browser's state of the session (the user's manual edits) into\n * the session as an <mxfile>: the embed/sync path can hand back a bare\n * <mxGraphModel>, and adopting it verbatim would strip a multi-page document\n * down to one page on the next write. Returns the state; the edit gate\n * compares against its raw xml.\n */\nfunction syncFromBrowser(session: Session) {\n    const browserState = sessionState(session.id)\n    if (browserState?.xml) {\n        session.xml = normalizeToMxfile(browserState.xml) ?? browserState.xml\n    }\n    return browserState\n}\n\n/**\n * Make xml the session's document: the previous one goes to History (with\n * the browser's image of it), the new one is pushed to the preview and\n * recorded in History (its image comes later, from the browser). seen: the\n * model wrote this exact XML knowing the state it built on, so edit_diagram\n * may follow without a get_diagram round-trip. source: what the version\n * cards call the entry (an opened file, an added page).\n */\nfunction commitDocument(\n    session: Session,\n    xml: string,\n    seen: boolean,\n    browserSvg?: string,\n    source?: HistorySource,\n) {\n    if (session.xml) keepInHistory(session.id, session.xml, browserSvg)\n    session.xml = xml\n    setState(session.id, xml)\n    session.lastSeenXml = seen ? xml : \"\"\n    addHistory(session.id, xml, \"\", source)\n}\n\n// The drawing guide plus the user's own rules from instructions.md, read\n// on every call so edits apply without restarting the host\nconst guideText = () => guideWithCustomInstructions(DRAWING_GUIDE)\n\n// The same guide as start_session, for hosts that show prompts to the user\nserver.registerPrompt(\n    \"diagram-workflow\",\n    {\n        description: \"Guidelines for creating and editing draw.io diagrams\",\n    },\n    () => ({\n        messages: [\n            {\n                role: \"user\",\n                content: { type: \"text\", text: guideText() },\n            },\n        ],\n    }),\n)\n\n// Tool: get_drawing_guide\nregisterTool(\n    \"get_drawing_guide\",\n    {\n        title: \"Get drawing guide\",\n        description:\n            \"Return the drawing guide: XML format, layout, edge routing, style and editing rules. \" +\n            \"start_session already returns it; call this only if the guide is no longer in your context. \" +\n            \"With topic, returns a short XML reference for tables, layers or groups.\",\n        inputSchema: {\n            topic: z\n                .enum([\"tables\", \"layers\", \"groups\"])\n                .optional()\n                .describe(\n                    \"Return only the XML reference for this topic instead of the whole guide.\",\n                ),\n        },\n        annotations: { readOnlyHint: true, openWorldHint: false },\n    },\n    async ({ topic }) => ok(topic ? XML_REFERENCE[topic] : guideText()),\n)\n\n// Tool: get_shape_library\nregisterTool(\n    \"get_shape_library\",\n    {\n        title: \"Get shape library\",\n        description:\n            \"Get the style syntax and shape names of a draw.io icon library. Call this BEFORE drawing with \" +\n            \"cloud, network or other icon shapes, and use the exact names it returns; never guess them.\\n\\n\" +\n            `Libraries:\\n${SHAPE_LIBRARY_LIST}`,\n        inputSchema: {\n            library: z\n                .string()\n                .describe(\"Library name, e.g. aws4, kubernetes, flowchart\"),\n        },\n        annotations: { readOnlyHint: true, openWorldHint: false },\n    },\n    async ({ library }) => {\n        const found = await getShapeLibrary(library)\n        return found.ok ? ok(found.text) : fail(found.error)\n    },\n)\n\n// On Windows the open package starts PowerShell with an encoded command,\n// which Kaspersky blocks as PowerShell started from a script (#998).\n// cmd's start hands the URL to the default browser instead\nasync function openBrowser(url: string) {\n    if (process.platform !== \"win32\") return open(url)\n    spawn(`start \"\" \"${url}\"`, {\n        shell: true,\n        stdio: \"ignore\",\n        windowsHide: true,\n    })\n        .on(\"error\", (err) => log.warn(`Could not open the browser: ${err}`))\n        .unref()\n}\n\n// Tool: start_session\nregisterTool(\n    \"start_session\",\n    {\n        title: \"Start session\",\n        description:\n            \"Start a new diagram session, or continue a saved one with session_id, and open the browser for real-time preview. \" +\n            \"Starts an embedded server and opens a browser window with draw.io. \" +\n            \"The browser will show diagram updates as they happen. \" +\n            \"The result includes the drawing guide; follow it when drawing.\",\n        inputSchema: {\n            session_id: z\n                .string()\n                .regex(/^mcp-[a-z0-9-]{1,64}$/)\n                .optional()\n                .describe(\n                    \"Id of a saved diagram (from list_saved_diagrams, or the Session ID of an earlier start_session) to continue it with the same preview URL and auto-save file. Omit to start a new diagram.\",\n                ),\n        },\n        annotations: { destructiveHint: false, openWorldHint: false },\n    },\n    async ({ session_id }) => {\n        // Start embedded HTTP server\n        const port = await startHttpServer(config.port)\n\n        // Create session, or continue a saved one under its old id\n        const sessionId =\n            session_id ??\n            `mcp-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 8)}`\n        currentSession = { id: sessionId, xml: \"\", lastSeenXml: \"\" }\n\n        // Open the browser. BROWSER=none (the convention of CRA and Vite\n        // dev servers) skips it: the e2e tests and headless hosts set it\n        const browserUrl = previewUrl(port, sessionId)\n        if (process.env.BROWSER !== \"none\") await openBrowser(browserUrl)\n\n        // A saved diagram comes back from its file. lastSeenXml stays\n        // empty, so edit_diagram asks for get_diagram first.\n        const restored = sessionState(sessionId)\n        let intro = \"Session started successfully!\"\n        if (session_id) {\n            // blank: the browser asked first and nothing was saved\n            if (restored && !restored.blank) {\n                intro = `Resumed session ${sessionId}.\\n\\n${describePages(restored.xml)}\\n\\nCall get_diagram before edit_diagram.`\n            } else {\n                intro = `No saved diagram for ${sessionId}; starting blank.`\n            }\n        }\n\n        const savePath = autosaver.pathFor(sessionId)\n        const saveNote = savePath\n            ? `\\n\\nAuto-save: after every change the diagram is saved to ${savePath}. Never edit that file or load a changed copy of it; change the diagram with edit_diagram. To continue this diagram in a later conversation, call start_session with session_id=${sessionId}. list_saved_diagrams lists older diagrams.`\n            : \"\"\n        const rulesNote = `\\n\\nYour own drawing rules: write them in ${customInstructionsPath()} (Markdown, up to 5000 characters, read on every call).`\n        // The bundled draw.io is served from the preview's own origin; an\n        // external one (DRAWIO_BASE_URL, or a build without the copy) cannot\n        // be reached by the page's scripts\n        const originNote = isSameOriginDrawio()\n            ? \"\"\n            : `\\n\\nThe preview loads draw.io from ${DRAWIO_BASE_URL} (another origin): same-origin editor features are off.`\n\n        log.info(`Started session ${sessionId}, browser at ${browserUrl}`)\n\n        // A tab that opens by itself surprises the user unless the agent\n        // says what it is; last, after the long guide, so it is not missed\n        const noBrowser = process.env.BROWSER === \"none\"\n        // Also right under the link: the guide in between is long (#1058)\n        const linkNote = noBrowser\n            ? \"\\nPut this link in your reply, even if a screenshot fails later: the user opens it to see the preview.\"\n            : \"\"\n        const tabNote = noBrowser\n            ? \"Give the user the Browser URL above: the live preview of the diagram, where they can also edit it by hand; you see their edits.\"\n            : \"A browser tab with the live preview just opened. In your reply, tell the user in one sentence that it shows the diagram as you draw and that you see the edits they make there.\"\n        return ok(\n            `${intro}\\n\\nSession ID: ${sessionId}\\nBrowser URL: ${browserUrl}${linkNote}${originNote}${saveNote}${rulesNote}\\n\\n${guideText()}\\n\\n${tabNote}`,\n        )\n    },\n    { write: true },\n)\n\n/** \"2026-10-04 09:30\" in the server's local time */\nfunction formatLocalTime(date: Date): string {\n    const pad = (n: number) => String(n).padStart(2, \"0\")\n    return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`\n}\n\n// Tool: list_saved_diagrams\nregisterTool(\n    \"list_saved_diagrams\",\n    {\n        title: \"List saved diagrams\",\n        description:\n            \"List the diagrams saved by earlier sessions (auto-save files), newest first, with their pages. \" +\n            \"Continue one with start_session session_id=<id>; the file path also works with load_diagram.\",\n        inputSchema: {},\n        annotations: { readOnlyHint: true, openWorldHint: false },\n    },\n    async () => {\n        const dir = autosaver.dataDir()\n        if (!dir) {\n            return ok(\n                \"Auto-save is off (DRAWIO_DATA_DIR=off), so there are no saved diagrams.\",\n            )\n        }\n        const saved = autosaver.list()\n        if (saved.length === 0) return ok(`No saved diagrams in ${dir}.`)\n        const lines: string[] = []\n        for (const { sessionId, path, savedAt } of saved) {\n            // A file may hold compressed pages (saved by draw.io itself)\n            let pages = \"unreadable\"\n            try {\n                const loaded = parseDrawioFileContent(\n                    await readFile(path, \"utf-8\"),\n                )\n                const doc = loaded.ok ? parseMxfile(loaded.xml) : null\n                if (doc) {\n                    pages = listPagesFromDoc(doc)\n                        .map((p) => `${p.name} (${p.cellCount} cells)`)\n                        .join(\", \")\n                }\n            } catch (error) {\n                log.warn(`Could not read the saved diagram ${path}: ${error}`)\n            }\n            const current =\n                sessionId === currentSession?.id ? \"  (current)\" : \"\"\n            lines.push(\n                `${sessionId}  saved ${formatLocalTime(savedAt)}  pages: ${pages}  file: ${path}${current}`,\n            )\n        }\n        return ok(lines.join(\"\\n\"))\n    },\n)\n\n// Tool: create_new_diagram\nregisterTool(\n    \"create_new_diagram\",\n    {\n        title: \"Create new diagram\",\n        description: `Create a NEW diagram, REPLACING the whole document: every page and any unsaved user changes (the previous state stays in History). To add a tab use add_page; to change cells use edit_diagram.\n\nBefore using icon shapes (AWS, Azure, GCP, Kubernetes, Cisco...), call get_shape_library first. Follow the drawing guide returned by start_session (call get_drawing_guide if it is no longer in your context). Pass screenshot: true on the last call of a complex diagram to check the result.\n\nAccepted xml:\n1) Only the mxCell elements of one page (recommended). The server adds <mxfile>, <mxGraphModel>, <root> and the root cells \"0\" and \"1\":\n<mxCell id=\"2\" value=\"Shape\" style=\"rounded=1;\" x=\"40\" y=\"40\" w=\"120\" h=\"60\"/>\n2) A bare <mxGraphModel> with <root> (one page).\n3) A full <mxfile> with one or more <diagram> pages. Every page's <root> must start with <mxCell id=\"0\"/><mxCell id=\"1\" parent=\"0\"/>.\n\nRules: cells are siblings (never nested), ids are unique per page and start from \"2\", parent only for shapes inside a container, no XML comments, and shapes stay within x 0 to 800 and y 0 to 600. A style used by several cells is defined once with <mxStyle name=\"...\" value=\"...\"/> before the cells and used by name (see the drawing guide); html=1 and whiteSpace=wrap are added automatically.\n\nTo clear the canvas to one blank page, send only the two root cells <mxCell id=\"0\"/><mxCell id=\"1\" parent=\"0\"/>; the previous diagram stays in History.`,\n        inputSchema: {\n            xml: z\n                .string()\n                .describe(\n                    \"REQUIRED: the mxCell elements of one page, a bare <mxGraphModel>, or a full <mxfile> with one or more <diagram> pages.\",\n                ),\n            screenshot: screenshotSchema,\n        },\n        annotations: { openWorldHint: false },\n    },\n    async ({ xml: inputXml, screenshot }) => {\n        const session = activeSession()\n        // The pictures get_diagram showed as references go back in\n        const prepared = prepareNewDiagram(\n            restoreImageData(inputXml, session.xml),\n        )\n        if (!prepared.ok) {\n            log.error(prepared.error)\n            return fail(prepared.error)\n        }\n        if (prepared.fixes.length > 0) {\n            log.info(`XML auto-fixed: ${prepared.fixes.join(\", \")}`)\n        }\n        // Every later tool can assume session.xml is an mxfile\n        const xml = prepared.xml\n\n        log.info(`Setting diagram content, ${xml.length} chars`)\n\n        // The user's state goes to History before the AI overwrites it\n        const browserState = syncFromBrowser(session)\n        commitDocument(session, xml, true, browserState?.svg)\n        // A new document, in no file until it is exported\n        setSessionFile(session.id, null)\n\n        // Report page count back to the caller so the LLM learns whether\n        // multi-page worked or fell back to single.\n        const doc = parseMxfile(xml)\n        const pages = doc ? listPagesFromDoc(doc) : []\n        const pageSummary =\n            pages.length > 1\n                ? `${pages.length} pages: ${pages.map((p) => `${p.index}:${p.name}`).join(\", \")}`\n                : pages.length === 1\n                  ? `1 page: ${pages[0].name}`\n                  : \"no pages parsed\"\n\n        log.info(`Diagram content set successfully (${pageSummary})`)\n\n        // Only the root cells: the model asked for an empty canvas\n        // (several empty pages get the page summary)\n        const cleared = !hasCells(xml) && pages.length <= 1\n        const content: CallToolResult[\"content\"] = [\n            {\n                type: \"text\",\n                text: cleared\n                    ? \"Canvas cleared: one blank page. The previous diagram is in History.\"\n                    : `Diagram content set successfully!\\n\\nThe diagram is now visible in your browser.\\n\\nXML length: ${xml.length} characters\\n${pageSummary}\\n\\n${outlineNote()}`,\n            },\n        ]\n        // The page on screen: the new document's first page after a full\n        // load, or the page the user was viewing when the write went on the\n        // canvas in place (both are the model's own work)\n        if (screenshot ?? config.autoScreenshot) {\n            const shot = await captureScreenshot(\n                session.id,\n                xml,\n                {},\n                AFTER_WRITE_NEXT,\n            )\n            content.push(\n                ...(shot.ok\n                    ? shot.content\n                    : [\n                          {\n                              type: \"text\" as const,\n                              text: `Screenshot skipped: ${shot.note}`,\n                          },\n                      ]),\n            )\n        }\n        return { content }\n    },\n    { write: true, needsSession: true },\n)\n\n// Tool: load_diagram\nregisterTool(\n    \"load_diagram\",\n    {\n        title: \"Load diagram file\",\n        description:\n            \"Load a .drawio diagram into the current session, REPLACING the entire diagram (all pages). \" +\n            \"To change an existing file, load it here, edit with edit_diagram, then export_diagram to the same path; never rewrite the file by hand. \" +\n            \"Provide ONE of two mutually exclusive sources: 'path' (the server reads the file from disk — you do NOT need to read the file yourself or pass its XML through create_new_diagram) \" +\n            \"or 'xml' (the raw file content you already have — from another tool, a repository read, or an API response — so no temporary file needs to be written first). \" +\n            \"Both accept plain XML and draw.io's compressed save format. \" +\n            \".drawio.svg (Editable SVG, the format export_diagram writes) is accepted too; .png files (also draw.io's editable PNG) and plain .svg files cannot be loaded.\\n\\n\" +\n            \"After loading from 'path' (or from compressed 'xml'), call get_diagram before edit_diagram — you haven't seen the file's cell IDs yet. \" +\n            \"Plain-XML 'xml' content you supplied yourself is already known and can be edited immediately.\",\n        inputSchema: {\n            path: z\n                .string()\n                .optional()\n                .describe(\n                    \"Path to the .drawio or .drawio.svg file to load (e.g. /Users/me/diagram.drawio or ~/diagram.drawio). Relative paths resolve against the MCP server's working directory, which is often not your project. Mutually exclusive with 'xml'.\",\n                ),\n            xml: z\n                .string()\n                .optional()\n                .describe(\n                    \"Raw .drawio file content: a plain <mxfile>/<mxGraphModel>, or draw.io's compressed save format. Use when the content is already in hand (another tool's output, a repository read, an API response). Mutually exclusive with 'path'.\",\n                ),\n        },\n        annotations: { openWorldHint: false },\n    },\n    async ({ path, xml: inlineXml }) => {\n        // Argument validation comes before the session check: a bad\n        // argument is a caller error and should be reported as such.\n        if (path !== undefined && inlineXml !== undefined) {\n            return fail(\"Provide either 'path' or 'xml', not both.\")\n        }\n        if (path === undefined && inlineXml === undefined) {\n            return fail(\n                \"Provide either 'path' (a .drawio file to read) or 'xml' (the file's content).\",\n            )\n        }\n        if (!currentSession) return fail(NO_SESSION)\n        const session = currentSession\n\n        // Exactly one of path/xml is present (validated above).\n        let content = \"\"\n        let sourceLabel = \"\"\n        if (inlineXml !== undefined) {\n            content = inlineXml\n            sourceLabel = \"inline XML\"\n        } else if (path !== undefined) {\n            const absolutePath = resolve(expandHome(path))\n            try {\n                // A pipe or device could be read forever, and the other\n                // write tools wait for this one\n                if (!(await stat(absolutePath)).isFile()) {\n                    throw new Error(\"not a regular file\")\n                }\n                content = await readFile(absolutePath, \"utf-8\")\n            } catch (e) {\n                const msg = e instanceof Error ? e.message : String(e)\n                return fail(`Cannot read file ${absolutePath}: ${msg}`)\n            }\n            sourceLabel = absolutePath\n        }\n\n        const loaded = parseDrawioFileContent(content)\n        if (!loaded.ok) return fail(loaded.error)\n        const xml = loaded.xml\n\n        log.info(`Loading diagram from ${sourceLabel} (${xml.length} chars)`)\n\n        // The user's state goes to History before the file replaces it.\n        // Edit-gate semantics by source:\n        // - 'path': the model only supplied a path, so it doesn't know\n        //   the file's cell IDs — keep the gate (one get_diagram first).\n        // - plain 'xml': the model supplied the exact content, same\n        //   rationale as create_new_diagram — record it as seen.\n        // - compressed 'xml': the session now holds the decompressed\n        //   form, which the model cannot derive from the compressed\n        //   input — keep the gate.\n        const browserState = syncFromBrowser(session)\n        const markSeen = inlineXml !== undefined && !loaded.hadCompressedPages\n        commitDocument(session, xml, markSeen, browserState?.svg, \"load\")\n        // The preview names the file (inline XML is in none)\n        setSessionFile(session.id, path !== undefined ? sourceLabel : null)\n\n        const pageSummary = describePages(xml)\n        log.info(`Diagram loaded (${pageSummary})`)\n\n        const gateHint = markSeen\n            ? \"\"\n            : \"\\n\\nCall get_diagram before edit_diagram — you haven't seen this file's cell IDs yet.\"\n        // The preview is a copy: the file changes only when it is exported\n        const saveHint =\n            path !== undefined\n                ? `\\n\\nEdits change the preview, not the file. When the changes are done, call export_diagram with path ${sourceLabel} to save them back to the file.`\n                : \"\"\n\n        return ok(\n            `Diagram loaded from ${sourceLabel}!\\n\\nThe diagram is now visible in your browser.\\n\\n${pageSummary}${gateHint}${saveHint}\\n\\n${outlineNote()}`,\n        )\n    },\n    { write: true },\n)\n// Tool: edit_diagram\nregisterTool(\n    \"edit_diagram\",\n    {\n        title: \"Edit diagram\",\n        description:\n            \"Edit a specific page in the current diagram by ID-based operations (update/add/delete cells).\\n\\n\" +\n            \"All-or-nothing: if any operation fails, nothing is applied and every failure is listed.\\n\\n\" +\n            \"Freshness: the server remembers the last diagram state you have seen, and rejects this call \" +\n            \"only if the user edited the diagram in the browser since then. You do NOT need to call \" +\n            \"get_diagram before every edit: a rejected call changes nothing and includes the current XML \" +\n            \"of the page, so you can rebuild your operations and retry.\\n\\n\" +\n            \"Call get_diagram first only when you don't know the current diagram content (cell IDs, \" +\n            \"structure) — e.g. the diagram wasn't created in this conversation, or you're unsure your \" +\n            \"memory of it is accurate.\\n\\n\" +\n            \"Multi-page targeting:\\n\" +\n            \"- page_id / page_name / page_index are optional; when all omitted, the FIRST page is targeted\\n\" +\n            \"- Use list_pages to discover what pages exist\\n\\n\" +\n            \"Operations:\\n\" +\n            \"- add: Add a new cell. Provide cell_id (new unique id within the page) and new_xml. One cell per operation.\\n\" +\n            \"- update: Replace an existing cell by its id. Provide cell_id and complete new_xml.\\n\" +\n            \"- delete: Remove a cell by its id. Only cell_id is needed. Its children and connected edges are deleted too, so give only a container's id.\\n\\n\" +\n            \"For add/update, new_xml is the complete mxCell (inside its <object> wrapper when it has custom data, see the drawing guide) in the compact form (a shape with x, y, w, h; an edge with source and target). No XML comments. \" +\n            'Every \" inside new_xml must be escaped as \\\\\" in the JSON.\\n\\n' +\n            \"Example - Add a rectangle on the default (first) page:\\n\" +\n            '{\"operations\": [{\"operation\": \"add\", \"cell_id\": \"rect-1\", \"new_xml\": \"<mxCell id=\\\\\"rect-1\\\\\" value=\\\\\"Hello\\\\\" style=\\\\\"rounded=1;\\\\\" x=\\\\\"100\\\\\" y=\\\\\"100\\\\\" w=\\\\\"120\\\\\" h=\\\\\"60\\\\\"/>\"}]}\\n\\n' +\n            \"Example - Delete a cell on the default page:\\n\" +\n            '{\"operations\": [{\"operation\": \"delete\", \"cell_id\": \"rect-1\"}]}',\n        inputSchema: {\n            ...pageSelectorSchema,\n            operations: z\n                .array(\n                    z.object({\n                        operation: z\n                            .enum([\"update\", \"add\", \"delete\"])\n                            .describe(\n                                \"Operation to perform: add, update, or delete\",\n                            ),\n                        cell_id: z\n                            .string()\n                            .describe(\n                                \"The id of the mxCell. Must match the id attribute in new_xml.\",\n                            ),\n                        new_xml: z\n                            .string()\n                            .optional()\n                            .describe(\n                                \"Complete mxCell XML element (required for update/add)\",\n                            ),\n                    }),\n                )\n                .describe(\"Array of operations to apply\"),\n            screenshot: screenshotSchema,\n        },\n        annotations: { openWorldHint: false },\n    },\n    async ({ operations, page_id, page_name, page_index, screenshot }) => {\n        const session = activeSession()\n\n        // Fetch latest state from browser\n        const browserState = syncFromBrowser(session)\n        if (browserState?.xml) {\n            log.info(\"Fetched latest diagram state from browser\")\n        }\n\n        if (!session.xml) {\n            return fail(\n                \"No diagram to edit. Please create a diagram first with create_new_diagram.\",\n            )\n        }\n\n        const pageSelector: PageSelector = { page_id, page_name, page_index }\n\n        // Enforce workflow: the model must have seen the current diagram\n        // state. Content comparison instead of a wall-clock timeout —\n        // slow reasoning between get_diagram and edit_diagram is fine as\n        // long as nothing changed in the browser meanwhile (#885).\n        const gate = checkEditGate(session.lastSeenXml, browserState?.xml ?? \"\")\n        if (!gate.ok) {\n            log.warn(\n                gate.reason === \"stale\"\n                    ? \"edit_diagram rejected: the browser has changes the model has not seen\"\n                    : \"edit_diagram rejected: the model has not seen the diagram yet\",\n            )\n            // The error carries the current page, so the model has now\n            // seen it and can retry without a get_diagram round-trip,\n            // unless other pages changed too.\n            const liveXml = browserState?.xml || session.xml\n            // What the model saw, before markPageSeen records the live state\n            const before = session.lastSeenXml\n            session.lastSeenXml = markPageSeen(\n                session.lastSeenXml,\n                liveXml,\n                pageSelector,\n            )\n            const reason =\n                gate.reason === \"stale\"\n                    ? \"The diagram changed in the browser since you last saw it (e.g. manual user edits). No changes were made.\"\n                    : \"You have not seen this diagram yet, so no changes were made.\"\n            // Per-cell summary of the user's changes, when they can be compared\n            const summary = describeChanges(before, liveXml)\n            const next =\n                session.lastSeenXml === liveXml\n                    ? \"Build your operations on this XML and retry.\"\n                    : `${OTHER_PAGES_UNSEEN} Call get_diagram without a page selector, then retry.`\n            return fail(\n                `${reason}\\n\\n${summary ? `${summary}\\n\\n` : \"\"}Current XML of ${describeSelector(pageSelector)}:\\n\\n${foldCells(targetPageXml(session.xml, pageSelector))}\\n\\n${next}`,\n            )\n        }\n\n        log.info(\n            `Editing diagram with ${operations.length} operation(s) on ${describeSelector(pageSelector)}`,\n        )\n\n        const outcome = editDiagram(\n            session.xml,\n            operations as DiagramOperation[],\n            pageSelector,\n        )\n        if (!outcome.ok) {\n            log.warn(`Edit rejected: ${outcome.errors.join(\"; \")}`)\n            return fail(\n                outcome.pageError\n                    ? outcome.errors[0]\n                    : `No changes were made because ${outcome.errors.length} operation(s) failed:\\n${outcome.errors.map((e) => `- ${e}`).join(\"\\n\")}\\n\\nCurrent XML of ${describeSelector(pageSelector)}:\\n\\n${foldCells(targetPageXml(session.xml, pageSelector))}\\n\\nFix the operations against this XML and retry.`,\n            )\n        }\n        if (outcome.fixes.length > 0) {\n            log.info(`new_xml auto-fixed: ${outcome.fixes.join(\"; \")}`)\n        }\n        const result = outcome.xml\n\n        // The pre-edit state goes to History for undo, only once the edit\n        // applied: a rejected edit returns above without leaving a phantom\n        // history entry.\n        commitDocument(session, result, true, browserState?.svg)\n\n        log.info(`Diagram edited successfully`)\n\n        // The preview's version card counts only real changes: say which\n        // updates changed nothing, so the model can tell the user\n        const { unchanged } = outcome\n        const unchangedNote =\n            unchanged.length > 0\n                ? ` ${unchanged.length} of them changed nothing (id ${unchanged.join(\", \")} already matched), so ${outcome.applied - unchanged.length} operation(s) changed the diagram.`\n                : \"\"\n        const content: CallToolResult[\"content\"] = [\n            {\n                type: \"text\",\n                text: `Diagram edited successfully!\\n\\nApplied ${outcome.applied} operation(s) on ${describeSelector(pageSelector)}.${unchangedNote}\\n\\n${outlineNote()}`,\n            },\n        ]\n        // Without a selector the edit went to the first page, while the\n        // page on screen may be another tab: name the page, so the PNG\n        // shows the edited one (a pageId export leaves the view alone)\n        if (screenshot ?? config.autoScreenshot) {\n            const shot = await captureScreenshot(\n                session.id,\n                result,\n                hasPageSelector(pageSelector)\n                    ? pageSelector\n                    : { page_index: 0 },\n                AFTER_WRITE_NEXT,\n            )\n            content.push(\n                ...(shot.ok\n                    ? shot.content\n                    : [\n                          {\n                              type: \"text\" as const,\n                              text: `Screenshot skipped: ${shot.note}`,\n                          },\n                      ]),\n            )\n        }\n        return { content }\n    },\n    { write: true, needsSession: true },\n)\n\n// Tool: get_diagram\nregisterTool(\n    \"get_diagram\",\n    {\n        title: \"Get diagram\",\n        description:\n            \"Get the current diagram XML (fetches latest from browser, including user's manual edits). \" +\n            \"Call this when you don't know the current diagram content (cell IDs, pages, structure) — \" +\n            \"e.g. before editing a diagram you didn't create in this conversation, or after edit_diagram \" +\n            \"was rejected because the user changed the diagram in the browser.\\n\\n\" +\n            \"Returns the full <mxfile> by default. If a page selector is provided, returns just that page's <mxGraphModel> embedded in a one-page <mxfile> wrapper.\",\n        inputSchema: {\n            ...pageSelectorSchema,\n        },\n        annotations: { readOnlyHint: true, openWorldHint: false },\n    },\n    async ({ page_id, page_name, page_index }) => {\n        // start_session may replace currentSession while this waits\n        const session = activeSession()\n        // Request browser to push fresh state and wait for it (an\n        // expired session first gets its saved file back to sync)\n        let staleNote = \"\"\n        restoreSavedSession(session.id)\n        const syncRequested = requestSync(session.id)\n        if (syncRequested) {\n            const synced = await waitForSync(session.id)\n            if (!synced) {\n                log.warn(\"get_diagram: sync timeout - state may be stale\")\n                staleNote =\n                    \"\\n\\nNote: the browser did not respond, so this XML may not include the user's latest manual edits (is the preview tab open?).\"\n            }\n        }\n\n        // Fetch latest state from browser\n        const browserState = syncFromBrowser(session)\n\n        if (!session.xml) {\n            return ok(\n                \"No diagram exists yet. Use create_new_diagram to create one.\",\n            )\n        }\n\n        const pageSelector: PageSelector = { page_id, page_name, page_index }\n\n        // The model is now looking at the current state. Record the raw\n        // store value — the gate's fast path is plain string equality\n        // against the store, with a structural comparison as fallback.\n        const liveXml = browserState?.xml || session.xml\n        // What the user changed since the model last looked, computed\n        // before lastSeenXml is overwritten below\n        const changes = describeChanges(session.lastSeenXml, liveXml)\n        const changesNote = changes ? `\\n\\nNote: ${changes}` : \"\"\n        const pageList = describePages(\n            session.xml,\n            \"No <mxfile> wrapper detected (legacy single-page session).\",\n        )\n\n        // No selector → return full mxfile\n        if (!hasPageSelector(pageSelector)) {\n            session.lastSeenXml = liveXml\n            const shown = foldCells(session.xml)\n            const note = imageRefNote(shown)\n            return ok(\n                `Current diagram XML. ${COMPACT_NOTE}\\n\\n${shown}\\n\\n${note ? `${note}\\n\\n` : \"\"}${pageList}${staleNote}${changesNote}`,\n            )\n        }\n\n        // Selector → return a single-page projection\n        const projection = projectPage(session.xml, pageSelector)\n        if (!projection.ok) {\n            return fail(\n                projection.reason === \"parse\"\n                    ? `a page selector was given but the current session XML could not be parsed as a multi-page <mxfile> (it may be a legacy single-page document or malformed), so it has no addressable pages.\\n\\n${pageList}`\n                    : `Page ${describeSelector(pageSelector)} not found.\\n\\n${pageList}`,\n            )\n        }\n        // One page shown counts for all only if the others are as the\n        // model saw them last\n        session.lastSeenXml = markPageSeen(\n            session.lastSeenXml,\n            liveXml,\n            pageSelector,\n        )\n        const otherPagesNote =\n            session.lastSeenXml === liveXml\n                ? \"\"\n                : `\\n\\nNote: ${OTHER_PAGES_UNSEEN} Call get_diagram without a page selector before editing.`\n        const shown = foldCells(projection.xml)\n        const note = imageRefNote(shown)\n        return ok(\n            `Page ${projection.index} (\"${projection.name}\"). ${COMPACT_NOTE}\\n\\n${shown}\\n\\n${note ? `${note}\\n\\n` : \"\"}${pageList}${staleNote}${changesNote}${otherPagesNote}`,\n        )\n    },\n    { needsSession: true },\n)\n\n// Tool: get_selection\nregisterTool(\n    \"get_selection\",\n    {\n        title: \"Get selection\",\n        description:\n            \"Return the cells the user has selected in the preview: their ids and labels, for edges the source and target ids, for shapes the position and size, and the page they are on. \" +\n            'Call this when the user refers to what they selected (\"this box\", \"these arrows\", \"the selected shapes\"), then act on the ids with edit_diagram. ' +\n            \"Says when nothing is selected. Needs the preview tab to be open.\",\n        inputSchema: {},\n        annotations: { readOnlyHint: true, openWorldHint: false },\n    },\n    async () => {\n        const sessionId = activeSession().id\n        // The classic preview page never answers: it has no access to the\n        // editor (the shell reads it through the same-origin frame). It is\n        // also what opens while the shell is not built\n        if (activePreviewUi() !== \"shell\") {\n            return ok(\n                \"The classic preview page cannot read the selection (DRAWIO_PREVIEW_UI=classic, or the canvas shell is not built: run npm run build in packages/mcp-server). Ask the user which shapes they mean, or call get_diagram.\",\n            )\n        }\n        if (previewStalled(sessionId))\n            return fail(previewStalledNote(sessionId))\n        if (sessionState(sessionId)?.lastPolled === undefined) {\n            return fail(previewNotOpenNote(sessionId))\n        }\n        const answer = await readSelection(sessionId)\n        if (!answer) {\n            return fail(\n                \"Reading the selection timed out. Make sure the preview tab is open and in front.\",\n            )\n        }\n        return ok(\n            describeSelection(\n                answer,\n                isSameOriginDrawio() ? null : DRAWIO_BASE_URL,\n            ),\n        )\n    },\n    { needsSession: true },\n)\n\n// The browser bridge has one export slot per session, so export requests\n// run one at a time: a concurrent call waits for the previous one.\nlet exportQueue: Promise<unknown> = Promise.resolve()\n\n/**\n * Ask the browser to export (optionally via a page projection) and poll for\n * the resulting image data. Resolves to undefined on timeout.\n */\nfunction exportViaBrowser(\n    sessionId: string,\n    format: ExportFormat,\n    projectionXml?: string,\n    options?: ExportOptions,\n): Promise<string | undefined> {\n    const run = exportQueue.then(async () => {\n        requestExport(sessionId, format, projectionXml, options)\n\n        // A projection export does an extra load + render round-trip in the\n        // browser, so give it a longer window. Re-read the live store entry\n        // each tick: setState() (from a concurrent autosave or tool call)\n        // replaces the Map entry with a new object, so a captured reference\n        // would go stale and never observe the browser's exportData.\n        const timeoutMs = projectionXml ? 15000 : 10000\n        const start = Date.now()\n        let exportData: string | undefined\n        while (Date.now() - start < timeoutMs) {\n            exportData = getState(sessionId)?.exportData\n            if (exportData) break\n            await new Promise((r) => setTimeout(r, 200))\n        }\n        const live = getState(sessionId)\n        if (live) {\n            live.exportData = undefined\n            live.exportFormat = undefined\n            live.exportXml = undefined\n            live.exportOptions = undefined\n            live.exportId = undefined\n        }\n        return exportData\n    })\n    exportQueue = run.catch(() => {})\n    return run\n}\n\n/**\n * True when the preview tab polled before but has gone quiet. Browsers\n * slow down timers in background tabs (Chrome: about once a minute after\n * 5 minutes hidden), so an export would just time out.\n */\nfunction previewStalled(sessionId: string): boolean {\n    const lastPolled = getState(sessionId)?.lastPolled\n    return lastPolled !== undefined && Date.now() - lastPolled > 10_000\n}\n\n/**\n * `next` is what the model does once the tab is in front. The default\n * suits screenshot_diagram and export_diagram; a write tool whose edit\n * already succeeded must not run again, so it points to screenshot_diagram.\n */\nfunction previewStalledNote(sessionId: string, next = \"then retry\") {\n    return `The preview tab is not responding (browsers pause background tabs). Ask the user to bring the preview tab to the front (${previewUrl(getServerPort(), sessionId)}), ${next}.`\n}\n\n// The link again, as an agent that only sees \"not open\" tends to tell the\n// user the preview is broken and leave the link out of its reply (#1058)\nfunction previewNotOpenNote(sessionId: string) {\n    return `The preview tab is not open, or has not connected yet. Give the user the preview link ${previewUrl(getServerPort(), sessionId)} in your reply and ask them to open it; screenshots and exports work once it is open.`\n}\n\n// Exported images get a margin, and a PNG a white background unless asked\n// otherwise (draw.io keeps a page's own background color over it); the\n// preview passes these on to draw.io's export\nconst IMAGE_MARGIN = 20\nfunction imageOptions(\n    format: ExportFormat,\n    transparent = false,\n): ExportOptions {\n    if (format !== \"png\") return { border: IMAGE_MARGIN }\n    return transparent\n        ? { border: IMAGE_MARGIN, transparent: true }\n        : { border: IMAGE_MARGIN, background: \"#ffffff\" }\n}\n\n/** A PNG's size from its IHDR chunk, which always comes first */\nfunction pngSize(png: Buffer): { width: number; height: number } | null {\n    if (png.length < 24 || png.toString(\"ascii\", 12, 16) !== \"IHDR\") {\n        return null\n    }\n    return { width: png.readUInt32BE(16), height: png.readUInt32BE(20) }\n}\n\n/** The <diagram id> of the page a selector targets, for draw.io's pageId. */\nfunction pageIdFor(xml: string, selector: PageSelector): string | undefined {\n    const doc = parseMxfile(xml)\n    return (\n        (doc && findPageElement(doc, selector)?.element.getAttribute(\"id\")) ||\n        undefined\n    )\n}\n\n// Stalled-tab advice after a successful create_new_diagram or edit_diagram:\n// \"then retry\" would make the model run the write again\nconst AFTER_WRITE_NEXT = \"then call screenshot_diagram to see the result\"\n\n// Screenshot size: Claude Desktop caps a tool result at about 150,000\n// characters, so retry smaller above 140,000 base64 characters. (Claude\n// Code 2.1 accepted a 240,000 character image in testing.)\nconst SCREENSHOT_WIDTHS = [1000, 700]\nconst MAX_SCREENSHOT_CHARS = 140_000\n\n// Adapted from the web app's vision check (lib/validation-prompts.ts)\nconst SCREENSHOT_CHECKLIST = `Check this rendering of the diagram for:\n1. Overlapping shapes that cover each other or their labels (critical)\n2. Edges crossing shapes that are not their source or target (critical)\n3. Text that is cut off, overlapping or too small to read (warning)\n4. Layout problems: cramped shapes, poor spacing or misalignment (warning)\n5. Rendering errors: missing, incomplete or broken elements, such as an icon that did not load (critical)\n6. Labels on top of lines or shape borders, arrowheads ending on text or icons, edges crossing other edges (warning)\nName the elements that have a problem, for example \"the 'Login' box overlaps 'Register'\".\nGive concrete fixes, for example \"move 'Login' 50 px left\".\nIf there are critical issues, fix them with edit_diagram and take one more screenshot; fix the warnings in the same round when you can. Do at most two rounds of fixes. Diagrams with only 1 or 2 shapes pass unless something is clearly broken. Do not tell the user the check passed while problems remain: name the ones you left.`\n\n/**\n * Have the preview tab render a page of xml as a PNG. Returns the image\n * block and the checklist for the model, or the reason there is no image\n * (a sentence without an \"Error:\" prefix: screenshot_diagram reports it as\n * an error, the write tools as a skipped screenshot).\n */\nasync function captureScreenshot(\n    sessionId: string,\n    xml: string,\n    selector: PageSelector,\n    /** What to do once a stalled tab is in front (see previewStalledNote) */\n    next?: string,\n): Promise<\n    | { ok: true; content: CallToolResult[\"content\"] }\n    | { ok: false; note: string }\n> {\n    if (previewStalled(sessionId)) {\n        return { ok: false, note: previewStalledNote(sessionId, next) }\n    }\n    // The tab never polled (right after start_session, or the state was\n    // just restored from disk), so an export would only time out\n    if (getState(sessionId)?.lastPolled === undefined) {\n        return {\n            ok: false,\n            note: previewNotOpenNote(sessionId),\n        }\n    }\n    if (!hasCells(xml)) {\n        return { ok: false, note: \"The diagram is empty.\" }\n    }\n\n    let pageId: string | undefined\n    let projectionXml: string | undefined\n    if (hasPageSelector(selector)) {\n        const doc = normalizeToMxfile(xml) ?? xml\n        pageId = pageIdFor(doc, selector)\n        // A page without an id: load just that page and capture it, as\n        // export_diagram does\n        if (!pageId) {\n            const projection = projectPage(doc, selector)\n            if (!projection.ok) {\n                return {\n                    ok: false,\n                    note: `Page ${describeSelector(selector)} not found.`,\n                }\n            }\n            projectionXml = projection.xml\n        }\n    }\n\n    let data: string | undefined\n    for (const width of SCREENSHOT_WIDTHS) {\n        data = await exportViaBrowser(sessionId, \"png\", projectionXml, {\n            ...imageOptions(\"png\"),\n            width,\n            pageId,\n        })\n        if (!data || data.length <= MAX_SCREENSHOT_CHARS) break\n    }\n    if (!data) {\n        return {\n            ok: false,\n            note: \"Screenshot timed out. Make sure the preview tab is open and in front.\",\n        }\n    }\n    return {\n        ok: true,\n        content: [\n            {\n                type: \"image\",\n                data: data.replace(/^data:image\\/png;base64,/, \"\"),\n                mimeType: \"image/png\",\n            },\n            {\n                type: \"text\",\n                text: `Screenshot of ${hasPageSelector(selector) ? `page ${describeSelector(selector)}` : \"the page on screen\"}.\\n\\n${SCREENSHOT_CHECKLIST}`,\n            },\n        ],\n    }\n}\n\n// Tool: screenshot_diagram\nregisterTool(\n    \"screenshot_diagram\",\n    {\n        title: \"Screenshot diagram\",\n        description:\n            \"Render the diagram in the preview and return it as a PNG image, so you can see your own result. \" +\n            \"Call this once after drawing or heavily editing a complex diagram, then fix overlaps and edges that cross shapes. \" +\n            \"Without a page selector it shows the page on screen; with one it renders that page without changing what the user sees. Needs the preview tab to be open.\",\n        inputSchema: { ...pageSelectorSchema },\n        annotations: { readOnlyHint: true, openWorldHint: false },\n    },\n    async ({ page_id, page_name, page_index }) => {\n        const session = activeSession()\n        const xml = sessionState(session.id)?.xml || session.xml\n        const shot = await captureScreenshot(session.id, xml, {\n            page_id,\n            page_name,\n            page_index,\n        })\n        if (!shot.ok) return fail(shot.note)\n        return { content: shot.content }\n    },\n    { needsSession: true },\n)\n\n// Tool: export_diagram\nregisterTool(\n    \"export_diagram\",\n    {\n        title: \"Export diagram\",\n        description:\n            \"Export the current diagram to a file. Supports .drawio (XML), .png, .svg, and .drawio.svg (an SVG with the diagram embedded, which draw.io and load_diagram can open again). \" +\n            \"The format is auto-detected from the file extension, or can be specified explicitly. \" +\n            \"Images get a 20 px margin; a PNG has a white background (or the page's own background color) unless transparent is true.\\n\\n\" +\n            \"Multi-page behaviour:\\n\" +\n            \"- .drawio with NO page selector: writes the full <mxfile> (all pages).\\n\" +\n            \"- .drawio with a page selector: writes a single-page <mxfile> containing only that page.\\n\" +\n            \"- .png / .svg with NO page selector: exports the currently active page in the browser.\\n\" +\n            \"- .png with a page selector: renders that page without changing what the user sees.\\n\" +\n            \"- .svg / .drawio.svg with a page selector: temporarily loads that page into the browser, captures it, then restores the full document (the user sees a brief flicker).\",\n        inputSchema: {\n            ...pageSelectorSchema,\n            path: z\n                .string()\n                .describe(\n                    \"Absolute file path to save to (e.g. /Users/me/diagram.drawio, ~/diagram.png). Relative paths resolve against the MCP server's working directory, which is often not your project.\",\n                ),\n            format: z\n                .enum([\"drawio\", \"png\", \"svg\", \"drawio.svg\"])\n                .optional()\n                .describe(\n                    \"Export format. If omitted, detected from file extension. Defaults to drawio.\",\n                ),\n            transparent: z\n                .boolean()\n                .optional()\n                .describe(\n                    \"PNG only: a transparent background instead of white. Default false.\",\n                ),\n        },\n        annotations: { openWorldHint: false },\n    },\n    async ({\n        path: rawPath,\n        format,\n        transparent,\n        page_id,\n        page_name,\n        page_index,\n    }) => {\n        const path = expandHome(rawPath)\n        // start_session may replace currentSession while this waits\n        const session = activeSession()\n\n        // Detect format from extension if not specified\n        const lowerPath = path.toLowerCase()\n        const detectedFormat =\n            format ||\n            (lowerPath.endsWith(\".drawio.svg\")\n                ? \"drawio.svg\"\n                : lowerPath.endsWith(\".png\")\n                  ? \"png\"\n                  : lowerPath.endsWith(\".svg\")\n                    ? \"svg\"\n                    : \"drawio\")\n\n        // The .drawio file is written from the state, so get the\n        // user's latest edits into it first, as get_diagram does (the\n        // images are made by the browser from its canvas)\n        let syncNote = \"\"\n        if (detectedFormat === \"drawio\") {\n            restoreSavedSession(session.id)\n            if (!requestSync(session.id)) {\n                syncNote =\n                    \"\\n\\nNote: the preview was not reachable, so the file may not include the user's latest manual edits.\"\n            } else if (!(await waitForSync(session.id))) {\n                log.warn(\"export_diagram: sync timeout - state may be stale\")\n                syncNote =\n                    \"\\n\\nNote: the browser did not respond, so the file may not include the user's latest manual edits (is the preview tab open?).\"\n            }\n        }\n\n        // Fetch latest state, so a page selector works on a bare\n        // <mxGraphModel> pushed by the browser\n        const browserState = syncFromBrowser(session)\n        // A change while the file is written leaves it behind the preview\n        const changesBefore = changeCount(session.id)\n\n        if (!session.xml) {\n            return fail(\"No diagram to export. Please create a diagram first.\")\n        }\n\n        const pageSelector: PageSelector = { page_id, page_name, page_index }\n\n        // .drawio path - write XML directly (no browser round-trip).\n        if (detectedFormat === \"drawio\") {\n            let filePath = path\n            if (!filePath.toLowerCase().endsWith(\".drawio\")) {\n                filePath = `${filePath}.drawio`\n            }\n            const absolutePath = resolve(filePath)\n\n            let outXml = session.xml\n            if (hasPageSelector(pageSelector)) {\n                const projection = projectPage(session.xml, pageSelector)\n                if (!projection.ok) {\n                    return fail(\n                        projection.reason === \"parse\"\n                            ? \"Cannot parse current session XML as <mxfile>; cannot project a single page.\"\n                            : `Page ${describeSelector(pageSelector)} not found for export.`,\n                    )\n                }\n                outXml = projection.xml\n            }\n\n            await mkdir(dirname(absolutePath), { recursive: true })\n            await writeFile(absolutePath, outXml, \"utf-8\")\n            log.info(`Diagram exported to ${absolutePath}`)\n            // The whole diagram is in this file now: the preview names it\n            if (!hasPageSelector(pageSelector)) {\n                setSessionFile(\n                    session.id,\n                    absolutePath,\n                    changeCount(session.id) !== changesBefore,\n                )\n            }\n            return ok(\n                `Diagram exported successfully!\\n\\nFile: ${absolutePath}\\nSize: ${outXml.length} characters\\n${describePages(outXml)}${syncNote}`,\n            )\n        }\n\n        // PNG or SVG: request browser to export via iframe. Replace a\n        // known extension that does not match the format.\n        let filePath = path\n        const suffix = `.${detectedFormat}`\n        if (!lowerPath.endsWith(suffix)) {\n            const known = [\".drawio.svg\", \".drawio\", \".png\", \".svg\"].find((e) =>\n                lowerPath.endsWith(e),\n            )\n            if (known) filePath = filePath.slice(0, -known.length)\n            filePath = `${filePath}${suffix}`\n        }\n        const absolutePath = resolve(filePath)\n        // draw.io's name for an SVG with the diagram embedded\n        const browserFormat =\n            detectedFormat === \"drawio.svg\" ? \"xmlsvg\" : detectedFormat\n\n        if (!browserState) {\n            return fail(\"Session state not found. Is the browser open?\")\n        }\n        if (previewStalled(session.id)) {\n            return fail(previewStalledNote(session.id))\n        }\n        // The tab never polled, so the export would only time out\n        if (browserState.lastPolled === undefined) {\n            return fail(previewNotOpenNote(session.id))\n        }\n        // -----------------------------------------------------------------\n        // Page-targeted PNG/SVG export.\n        //\n        // drawio's JSON embed protocol has no working `selectPage` action,\n        // so to export a specific page we build a single-page <mxfile>\n        // projection and hand it to the browser bridge alongside the export\n        // request. The bridge loads the projection, waits for draw.io's own\n        // render, exports, then reloads the user's real document — entirely\n        // browser-side. The canonical session state is never mutated here,\n        // so there is no restore race and no concurrent-edit clobbering.\n        // -----------------------------------------------------------------\n        // PNG: draw.io renders any page by id, without touching the\n        // page on screen. SVG export has no page option, so it still\n        // needs the projection below.\n        let projectionXml: string | undefined\n        let pngPageId: string | undefined\n        if (hasPageSelector(pageSelector) && detectedFormat === \"png\") {\n            pngPageId = pageIdFor(session.xml, pageSelector)\n        }\n        if (hasPageSelector(pageSelector) && !pngPageId) {\n            const projection = projectPage(session.xml, pageSelector)\n            if (!projection.ok) {\n                return fail(\n                    projection.reason === \"parse\"\n                        ? \"Cannot parse current session XML as <mxfile>; cannot target page for export.\"\n                        : `Page ${describeSelector(pageSelector)} not found for export.`,\n                )\n            }\n            projectionXml = projection.xml\n        }\n\n        const pngTransparent = detectedFormat === \"png\" && transparent === true\n        const exportData = await exportViaBrowser(\n            session.id,\n            browserFormat,\n            projectionXml,\n            {\n                ...imageOptions(browserFormat, pngTransparent),\n                ...(pngPageId && { pageId: pngPageId }),\n            },\n        )\n\n        if (!exportData) {\n            return fail(\n                projectionXml\n                    ? \"Export timed out after loading the single-page projection. The browser may be closed or unresponsive.\"\n                    : \"Export timed out. Make sure the browser tab is open and the diagram is loaded.\",\n            )\n        }\n\n        // Decode and write; what the file holds goes in the result, so the\n        // model need not open it to check\n        const shows = hasPageSelector(pageSelector)\n            ? `page ${describeSelector(pageSelector)}`\n            : \"the page on screen\"\n        let details = \"\"\n        if (detectedFormat === \"png\") {\n            const base64 = exportData.replace(/^data:image\\/png;base64,/, \"\")\n            const png = Buffer.from(base64, \"base64\")\n            await mkdir(dirname(absolutePath), { recursive: true })\n            await writeFile(absolutePath, png)\n            const size = pngSize(png)\n            details = `Image: ${size ? `${size.width} x ${size.height} px, ` : \"\"}${pngTransparent ? \"transparent\" : \"white\"} background, ${IMAGE_MARGIN} px margin, showing ${shows}`\n        } else {\n            let svgContent = exportData\n            if (svgContent.startsWith(\"data:image/svg+xml;base64,\")) {\n                const base64 = svgContent.replace(\n                    /^data:image\\/svg\\+xml;base64,/,\n                    \"\",\n                )\n                svgContent = Buffer.from(base64, \"base64\").toString(\"utf-8\")\n            }\n            await mkdir(dirname(absolutePath), { recursive: true })\n            await writeFile(absolutePath, svgContent, \"utf-8\")\n            details = `Image: ${IMAGE_MARGIN} px margin, showing ${shows}`\n            if (detectedFormat === \"drawio.svg\") {\n                // The file holds the diagram too (one page with a selector)\n                details += `\\nEmbedded diagram: ${describePages(projectionXml ?? session.xml)}`\n                if (!projectionXml) {\n                    setSessionFile(\n                        session.id,\n                        absolutePath,\n                        changeCount(session.id) !== changesBefore,\n                    )\n                }\n            }\n        }\n\n        const written = await stat(absolutePath)\n        log.info(\n            `Diagram exported to ${absolutePath} (${detectedFormat}, ${written.size} bytes)`,\n        )\n        return ok(\n            `Diagram exported successfully!\\n\\nFile: ${absolutePath}\\nFormat: ${detectedFormat}\\nSize: ${written.size} bytes\\n${details}`,\n        )\n    },\n    { needsSession: true },\n)\n\n/**\n * Shared helper for page-CRUD tools.\n * Loads the latest session XML, normalises to mxfile if needed, returns a\n * parsed Document the caller can mutate, plus a writer that persists.\n */\nasync function loadMxfileForMutation(): Promise<\n    | {\n          ok: true\n          doc: Document\n          writeBack: (source?: HistorySource) => void\n      }\n    | { ok: false; message: string }\n> {\n    if (!currentSession) return { ok: false, message: NO_SESSION }\n    const session = currentSession\n    // Pull latest from browser so we don't clobber autosaved changes.\n    const browserState = syncFromBrowser(session)\n    if (!session.xml) {\n        return {\n            ok: false,\n            message:\n                \"No diagram exists yet. Use create_new_diagram first, then page tools.\",\n        }\n    }\n    // 